import { FormField } from "../../../../components/common/index.jsx";
import ReadOnlyPanel from "./ReadOnlyPanel.jsx";

export default function StepChapterItems({
  form,
  activeSpan,
  activeChapter,
  onChapterChange,
  onAddLine,
  onRemoveLine,
  onUpdateLine,
  chapterLocked = false,
}) {
  const chapters = activeSpan?.chapters ?? [];
  const items = activeChapter?.items ?? [];

  return (
    <div>
      {chapterLocked ? (
        <>
          <div className="emb-lock-banner">
            Locked — chapter cannot be changed; you may update line items and measurements
          </div>
          <ReadOnlyPanel
            title="Chapter"
            rows={[
              ["Name", activeChapter?.name ?? form.chapter],
              ["Code", activeChapter?.code],
            ]}
          />
        </>
      ) : (
        <FormField label="Chapter" required description="Work category for this entry">
          <select
            className="form-control"
            value={form.chapter ? `${form.chapter}|||${form.chapterId}` : ""}
            onChange={(e) => {
              const [name, chapterId] = e.target.value.split("|||");
              onChapterChange(name, chapterId);
            }}
            disabled={!activeSpan}
            style={{ opacity: !activeSpan ? 0.5 : 1 }}
          >
            <option value="">
              {activeSpan ? "Select chapter…" : "Complete span selection first"}
            </option>
            {chapters.map((ch) => (
              <option key={ch._id} value={`${ch.name}|||${ch._id}`}>
                {ch.name}
              </option>
            ))}
          </select>
        </FormField>
      )}

      {(activeChapter || chapterLocked) && (
        <div className="emb-meta-strip">
          {activeChapter ? (
            <>
              <strong>{items.length}</strong> schedule item{items.length !== 1 ? "s" : ""}{" "}
              under chapter <strong>{activeChapter.name}</strong>
            </>
          ) : (
            <>
              <strong>{form.lineItems.length}</strong> line item
              {form.lineItems.length !== 1 ? "s" : ""} on this entry
            </>
          )}
        </div>
      )}

      {(activeChapter || chapterLocked) && (
        <div>
          <div className="emb-line-table__toolbar">
            <span className="emb-line-table__title">Schedule line items</span>
            <button
              type="button"
              className="btn btn-outline btn-sm"
              onClick={onAddLine}
              style={{ fontSize: 11, padding: "4px 10px" }}
            >
              + Add row
            </button>
          </div>

          {form.lineItems.length === 0 ? (
            <div
              style={{
                padding: 16,
                textAlign: "center",
                border: "1px dashed var(--emb-border, var(--border))",
                borderRadius: 4,
                color: "#64748b",
                fontSize: 12,
              }}
            >
              Add a line item row to record work against this chapter
            </div>
          ) : (
            form.lineItems.map((li, idx) => (
              <div key={li._id} className="emb-line-row">
                <span className="emb-line-row__idx">{idx + 1}</span>
                <div>
                  <select
                    className="form-control"
                    value={li.label || ""}
                    onChange={(e) => {
                      const item = items.find((i) => i.label === e.target.value);
                      if (item) onUpdateLine(li._id, { ...item, label: item.label });
                    }}
                  >
                    <option value="">Select schedule item…</option>
                    {items.map((item) => (
                      <option key={item._id} value={item.label}>
                        {item.label} — {item.code}
                      </option>
                    ))}
                    {li.label &&
                      !items.some((i) => i.label === li.label) && (
                        <option value={li.label}>
                          {li.label}
                          {li.code ? ` — ${li.code}` : ""}
                        </option>
                      )}
                  </select>
                  {li.code && <span className="emb-line-row__code">{li.code}</span>}
                  {li.description && (
                    <div className="emb-line-row__desc">{li.description}</div>
                  )}
                </div>
                {form.lineItems.length > 1 && (
                  <button
                    type="button"
                    className="btn btn-danger btn-sm"
                    onClick={() => onRemoveLine(li._id)}
                    style={{ padding: "6px 8px", marginTop: 4 }}
                    aria-label="Remove line item"
                  >
                    ✕
                  </button>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}
