import { useState, useEffect, useMemo, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { PageHeader, Spinner } from "../../../components/common/index.jsx";
import "./entryForm.css";
import CollapsibleSection from "./components/CollapsibleSection.jsx";
import StepProject from "./components/StepProject.jsx";
import StepSpan from "./components/StepSpan.jsx";
import StepChapterItems from "./components/StepChapterItems.jsx";
import StepMeasurements from "./components/StepMeasurements.jsx";
import EntryLiveSummary from "./components/EntryLiveSummary.jsx";
import { Q, M, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery, useApiMutation } from "../../../apollo/useApi.js";
import { deepClean } from "../../../utils/helpers.js";
import { addLine, removeLine, updateLine } from "../common/index.js";
import {
  getSpanProjectId,
  getSpanId,
  idsMatch,
  calcDistance,
  parseChainageValue,
} from "./utils.js";
import useWideLayout from "./hooks/useWideLayout.js";

export default function NewEmbEntry() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const querySpanId = searchParams.get("spanId") ?? "";
  const wide = useWideLayout();
  const [createEmbEntry] = useApiMutation(M.activities.create, { fields: "_id" });
  const [saving, setSaving] = useState(false);
  const deepLinkPanelsSet = useRef(false);
  const [open, setOpen] = useState(() =>
    querySpanId
      ? { project: false, span: false, items: true, measurements: false }
      : { project: true, span: false, items: false, measurements: false },
  );
  const [form, setForm] = useState({
    projectId: "",
    spanId: querySpanId,
    chapter: "",
    chapterId: "",
    locationDescription: "",
    activityStartChain: "",
    activityEndChain: "",
    lineItems: [],
    remarks: "",
  });

  const set = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));

  const distanceProgressed = useMemo(
    () => calcDistance(form.activityStartChain, form.activityEndChain),
    [form.activityStartChain, form.activityEndChain],
  );

  const {
    data: projectsData,
    loading: projectsLoading,
    error: projectsError,
  } = useApiQuery(Q.projects.list, {
    fields: PRESETS.projectEntryForm,
    fetchPolicy: "cache-and-network",
    queryOptions: {
      fragments: [],
      pagination: "page limit totalPages totalDocuments",
    },
    variables: { page: 1, limit: 50 },
  });

  const projects = useMemo(
    () => projectsData?.projects?.data ?? [],
    [projectsData],
  );

  const {
    data: spanByIdData,
    loading: spanByIdLoading,
  } = useApiQuery(Q.spans.get, {
    fields: PRESETS.spanEntryForm,
    fetchPolicy: "cache-and-network",
    variables: { id: querySpanId },
    skip: !querySpanId,
  });
  const spanFromUrl = spanByIdData?.span ?? null;

  const deepLinkProjectId = getSpanProjectId(spanFromUrl);
  const effectiveProjectId = form.projectId || deepLinkProjectId;

  const {
    data: spansData,
    loading: spansLoading,
    error: spansError,
  } = useApiQuery(Q.spans.list, {
    fields: PRESETS.spanEntryForm,
    fetchPolicy: "cache-and-network",
    variables: {
      page: 1,
      limit: 50,
      projects: effectiveProjectId ? [effectiveProjectId] : undefined,
    },
    skip: !effectiveProjectId && !querySpanId,
  });

  const spans = useMemo(() => {
    const list = spansData?.spans?.data ?? [];
    if (!querySpanId || !spanFromUrl) return list;
    const urlSpanId = getSpanId(spanFromUrl);
    if (!urlSpanId) return list;
    if (list.some((s) => idsMatch(getSpanId(s), urlSpanId))) return list;
    return [spanFromUrl, ...list];
  }, [spansData, querySpanId, spanFromUrl]);

  const activeSpan = useMemo(() => {
    const sid = form.spanId || (querySpanId && spanFromUrl ? getSpanId(spanFromUrl) : "");
    if (!sid) return null;
    return (
      spans.find((s) => idsMatch(getSpanId(s), sid)) ??
      (spanFromUrl && idsMatch(getSpanId(spanFromUrl), sid) ? spanFromUrl : null)
    );
  }, [spans, form.spanId, querySpanId, spanFromUrl]);

  const projectOptions = useMemo(() => {
    const list = [...projects];
    const pid = getSpanProjectId(spanFromUrl);
    const p = spanFromUrl?.project;
    if (pid && !list.some((x) => x._id === pid)) {
      list.unshift({
        _id: pid,
        name: p?.name ?? "Project",
        code: p?.code ?? "",
        description: "",
        status: "",
      });
    }
    return list;
  }, [projects, spanFromUrl]);

  const activeProject =
    projects.find((p) => p._id === form.projectId) ??
    projectOptions.find((p) => p._id === form.projectId) ??
    null;
  const activeChapter =
    activeSpan?.chapters?.find((c) => c.name === form.chapter) ?? null;

  const sectionComplete = {
    project: !!form.projectId,
    span:
      !!form.spanId &&
      form.activityStartChain !== "" &&
      form.activityEndChain !== "" &&
      distanceProgressed != null,
    items:
      !!form.chapterId && form.lineItems.some((li) => li.label),
    measurements: form.lineItems.some((li) => li.label),
  };

  const canSubmit =
    sectionComplete.project &&
    sectionComplete.span &&
    sectionComplete.items;

  useEffect(() => {
    if (!querySpanId || !spanFromUrl) return;

    const spanId = getSpanId(spanFromUrl) || querySpanId.trim();
    const projectId = getSpanProjectId(spanFromUrl);
    const start = spanFromUrl.startPoint?.chainNumber;
    const end = spanFromUrl.endPoint?.chainNumber;

    setForm((prev) => ({
      ...prev,
      spanId,
      projectId: projectId || prev.projectId,
      activityStartChain:
        start != null ? String(start) : prev.activityStartChain,
      activityEndChain: end != null ? String(end) : prev.activityEndChain,
    }));

    if (projectId && !deepLinkPanelsSet.current) {
      deepLinkPanelsSet.current = true;
      setOpen({ project: false, span: false, items: true, measurements: false });
    }
  }, [querySpanId, spanFromUrl]);

  const handleProjectChange = (projectId) => {
    setForm((prev) => {
      if (prev.projectId === projectId) return prev;
      return {
        ...prev,
        projectId,
        spanId: "",
        chapter: "",
        chapterId: "",
        activityStartChain: "",
        activityEndChain: "",
        lineItems: [],
      };
    });
  };

  const handleSpanChange = (spanId) => {
    const span = spans.find((s) => idsMatch(getSpanId(s), spanId));
    setForm((prev) => ({
      ...prev,
      spanId,
      chapter: "",
      chapterId: "",
      lineItems: [],
      activityStartChain: span?.startPoint?.chainNumber?.toString() ?? "",
      activityEndChain: span?.endPoint?.chainNumber?.toString() ?? "",
    }));
  };

  const handleChapterChange = (name, chapterId) => {
    setForm((prev) => ({
      ...prev,
      chapter: name,
      chapterId,
      lineItems: [],
    }));
  };

  const handleAddLine = () => addLine(form, set);
  const handleRemoveLine = (id) => removeLine(form, set, id);
  const handleUpdateLine = (id, patch) => updateLine(form, set, id, patch);

  useEffect(() => {
    setForm((prev) => {
      if (!prev.chapterId || prev.lineItems.length > 0) return prev;
      return {
        ...prev,
        lineItems: [
          ...prev.lineItems,
          {
            _id: `li-${Date.now()}`,
            label: "",
            code: "",
            description: "",
            measurements: [],
            remarks: "",
          },
        ],
      };
    });
  }, [form.chapterId, form.lineItems.length]);

  const toggle = (key) =>
    setOpen((prev) => ({ ...prev, [key]: !prev[key] }));

  const handleSubmit = async () => {
    if (!canSubmit) return;
    try {
      setSaving(true);
      const chinageFrom = parseChainageValue(form.activityStartChain);
      const chinageTo = parseChainageValue(form.activityEndChain);

      await createEmbEntry({
        variables: {
          activityInput: {
            spanId: form.spanId,
            chapter: form.chapterId,
            locationDescription: form.locationDescription?.trim() || undefined,
            ...(chinageFrom != null ? { chinageFrom } : {}),
            ...(chinageTo != null ? { chinageTo } : {}),
            lineItems: form.lineItems
              .filter((li) => li.label)
              .map((li) =>
                deepClean(li, [
                  "__typename",
                  "localId",
                  "createdAt",
                  "updatedAt",
                  "cumulativeProgress",
                ]),
              ),
          },
        },
      });
      setSaving(false);
      navigate("/my-entries");
    } catch (error) {
      console.error("Submit error:", error);
      setSaving(false);
      alert("Submit failed. Please try again.");
    }
  };

  const lineItemCount = form.lineItems.filter((li) => li.label).length;

  const sections = [
    {
      key: "project",
      step: 1,
      title: "Project",
      summary: activeProject
        ? `${activeProject.name} (${activeProject.code})`
        : "Select a project",
      disabled: false,
      content: (
        <StepProject
          form={form}
          projects={projectOptions}
          projectsLoading={projectsLoading || (!!querySpanId && spanByIdLoading)}
          projectsError={projectsError}
          activeProject={activeProject}
          onProjectChange={handleProjectChange}
        />
      ),
    },
    {
      key: "span",
      step: 2,
      title: "Span & activity extent",
      summary: activeSpan
        ? `${activeSpan.name}${distanceProgressed != null ? ` · ${distanceProgressed} progressed` : ""}`
        : "Select span and chain range",
      disabled: !form.projectId && !deepLinkProjectId,
      content: (
        <StepSpan
          form={form}
          set={set}
          spans={spans}
          spansLoading={spansLoading && !spanFromUrl}
          spansError={spansError}
          activeSpan={activeSpan}
          onSpanChange={handleSpanChange}
          distanceProgressed={distanceProgressed}
          deepLinkSpanId={querySpanId}
        />
      ),
    },
    {
      key: "items",
      step: 3,
      title: "Chapter & line items",
      summary:
        activeChapter && lineItemCount
          ? `${activeChapter.name} · ${lineItemCount} item${lineItemCount !== 1 ? "s" : ""}`
          : activeChapter
            ? activeChapter.name
            : "Select chapter and work items",
      disabled: !sectionComplete.span,
      content: (
        <StepChapterItems
          form={form}
          activeSpan={activeSpan}
          activeChapter={activeChapter}
          onChapterChange={handleChapterChange}
          onAddLine={handleAddLine}
          onRemoveLine={handleRemoveLine}
          onUpdateLine={handleUpdateLine}
        />
      ),
    },
    {
      key: "measurements",
      step: 4,
      title: "Measurements",
      summary:
        lineItemCount > 0
          ? `${lineItemCount} item${lineItemCount !== 1 ? "s" : ""} to measure`
          : "Enter measurements for each item",
      disabled: !sectionComplete.items,
      content: <StepMeasurements form={form} updateLine={handleUpdateLine} />,
    },
  ];

  const formPanel = (
    <div
      className="emb-entry entry-form-compact"
      style={{ display: "flex", flexDirection: "column", gap: 8 }}
    >
      {sections.map((s) => (
        <CollapsibleSection
          key={s.key}
          step={s.step}
          title={s.title}
          summary={s.summary}
          isOpen={open[s.key]}
          isComplete={sectionComplete[s.key]}
          isDisabled={s.disabled}
          onToggle={() => toggle(s.key)}
        >
          {s.content}
        </CollapsibleSection>
      ))}

      <div className="emb-form-actions" style={{ display: "flex", gap: 10 }}>
        <button
          type="button"
          className="btn btn-outline"
          style={{ flex: 1, minHeight: 48, fontSize: 14 }}
          onClick={() => navigate("/my-entries")}
        >
          Cancel
        </button>
        <button
          type="button"
          className="btn btn-primary"
          style={{ flex: 2, minHeight: 48, fontSize: 14, fontWeight: 700 }}
          onClick={handleSubmit}
          disabled={saving || !canSubmit}
        >
          {saving ? (
            <Spinner size={16} color="var(--on-accent)" />
          ) : (
            "✓ Submit Entry"
          )}
        </button>
      </div>
    </div>
  );

  const summary = (
    <EntryLiveSummary
      form={form}
      activeProject={activeProject}
      activeSpan={activeSpan}
      activeChapter={activeChapter}
      distanceProgressed={distanceProgressed}
    />
  );

  return (
    <div
      className="fade-up emb-entry emb-entry-page"
      style={{ maxWidth: wide ? 1100 : 640, margin: "0 auto" }}
    >
      <PageHeader
        title="New e-MB Entry"
        subtitle="Field measurement book · site record"
      />

      {wide ? (
        <div style={{ display: "flex", gap: 20, alignItems: "flex-start" }}>
          <div style={{ flex: 1, minWidth: 0 }}>{formPanel}</div>
          <div style={{ width: 260, flexShrink: 0 }}>{summary}</div>
        </div>
      ) : (
        <>
          {formPanel}
          <div style={{ marginTop: 16 }}>{summary}</div>
        </>
      )}
    </div>
  );
}
