import { useState, useMemo, useEffect } from "react";
import { useLazyQuery } from "@apollo/client";
import { Q, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery } from "../../../apollo/useApi.js";
import {
  PageHeader,
  FormField,
  Spinner,
} from "../../../components/common/index.jsx";
import CollapsibleSection from "../../field_engineer/new-entry/components/CollapsibleSection.jsx";
import { buildSpanProgressReport } from "../../../utils/progressReport.js";
import { exportProgressReportXlsx } from "../../../utils/reportProgressExport.js";
import SpanProgressReportView from "./components/SpanProgressReportView.jsx";
import "../../field_engineer/new-entry/entryForm.css";

const REPORT_LIMIT = 5000;

const REPORT_ACTIVITIES_QUERY = Q.activities.list(PRESETS.activityReportDetail, {
  pagination: "totalDocuments",
});

const REPORT_SPAN_QUERY = Q.spans.get(PRESETS.spanReport);

export default function ReportsDashboard() {
  const today = new Date().toISOString().slice(0, 10);
  const firstOfMonth = today.slice(0, 8) + "01";
  const [from, setFrom] = useState(firstOfMonth);
  const [to, setTo] = useState(today);
  const [spanId, setSpanId] = useState("");
  const [reportSpanId, setReportSpanId] = useState("");
  const [filtersOpen, setFiltersOpen] = useState(true);

  useEffect(() => {
    setReportSpanId("");
  }, [spanId, from, to]);

  const { data: spansListData, loading: spansListLoading } = useApiQuery(
    Q.spans.list,
    {
      fields: PRESETS.spanReport,
      variables: { page: 1, limit: 200 },
      fetchPolicy: "cache-and-network",
    },
  );

  const spans = spansListData?.spans?.data ?? [];
  const selectedSpan = spans.find((s) => s._id === spanId) ?? null;

  const [
    fetchActivities,
    {
      data: activitiesData,
      loading: activitiesLoading,
      error: activitiesError,
    },
  ] = useLazyQuery(REPORT_ACTIVITIES_QUERY, { fetchPolicy: "network-only" });

  const [
    fetchReportSpan,
    {
      data: reportSpanData,
      loading: reportSpanLoading,
      error: reportSpanError,
    },
  ] = useLazyQuery(REPORT_SPAN_QUERY, { fetchPolicy: "network-only" });

  const loading = activitiesLoading || spansListLoading || reportSpanLoading;

  const generate = () => {
    if (!spanId) return;
    setReportSpanId(spanId);
    setFiltersOpen(false);
    fetchReportSpan({ variables: { id: spanId } });
    fetchActivities({
      variables: {
        limit: REPORT_LIMIT,
        span: [spanId],
        fromDate: new Date(from + "T00:00:00").toISOString(),
        toDate: new Date(to + "T23:59:59").toISOString(),
      },
    });
  };

  const reportSpan =
    reportSpanData?.span ??
    spans.find((s) => s._id === reportSpanId) ??
    selectedSpan;

  const reportData = useMemo(() => {
    const activities = activitiesData?.activities?.data;
    if (!activities || !reportSpan) return null;

    const total = activities.length;
    const approved = activities.filter((e) => e.status === "APPROVED").length;
    const rejected = activities.filter((e) => e.status === "REJECTED").length;
    const submitted = activities.filter((e) => e.status === "SUBMITTED").length;

    const progressRows = buildSpanProgressReport(reportSpan, activities, {
      fromDate: from,
      toDate: to,
    });

    return {
      total,
      approved,
      rejected,
      submitted,
      progressRows,
      spanName: reportSpan.name,
      projectName: reportSpan.project?.name,
    };
  }, [activitiesData, reportSpan, from, to]);

  const filterSummary = selectedSpan
    ? `${selectedSpan.name}${selectedSpan.project?.name ? ` · ${selectedSpan.project.name}` : ""} · ${from} → ${to}`
    : "Select span and date range";

  const filtersReady = !!spanId && !!from && !!to;
  const hasReport = reportData && reportSpanId === spanId;

  const handleExport = () => {
    if (!reportData?.progressRows?.length) {
      alert("No progress data to export. Generate a report with tracked targets first.");
      return;
    }
    exportProgressReportXlsx({
      rows: reportData.progressRows,
      spanName: reportData.spanName,
      projectName: reportData.projectName,
      from,
      to,
    });
  };

  return (
    <div className="fade-up emb-entry emb-entry-page">
      <PageHeader
        title="Reports"
        subtitle="Progress tracked against span targets"
      />

      <div style={{ width: "100%", marginBottom: 16 }}>
        <CollapsibleSection
          step={1}
          title="Report filters"
          summary={filterSummary}
          isOpen={filtersOpen}
          isComplete={filtersReady}
          isDisabled={false}
          onToggle={() => setFiltersOpen((o) => !o)}
        >
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <FormField
              label="Span"
              description="Activities are filtered to this span only"
            >
              <select
                className="form-control"
                value={spanId}
                onChange={(e) => setSpanId(e.target.value)}
                disabled={spansListLoading}
              >
                <option value="">
                  {spansListLoading ? "Loading spans…" : "Select a span…"}
                </option>
                {spans.map((s) => (
                  <option key={s._id} value={s._id}>
                    {s.name}
                    {s.project?.name ? ` · ${s.project.name}` : ""}
                  </option>
                ))}
              </select>
            </FormField>

            <div className="form-row">
              <FormField label="From date">
                <input
                  className="form-control"
                  type="date"
                  value={from}
                  onChange={(e) => setFrom(e.target.value)}
                />
              </FormField>
              <FormField label="To date">
                <input
                  className="form-control"
                  type="date"
                  value={to}
                  onChange={(e) => setTo(e.target.value)}
                />
              </FormField>
            </div>

            <button
              type="button"
              className="btn btn-primary"
              onClick={generate}
              disabled={loading || !filtersReady}
              style={{ alignSelf: "flex-start", minHeight: 44 }}
            >
              {loading ? (
                <Spinner size={14} color="var(--on-accent)" />
              ) : (
                "Generate report"
              )}
            </button>

            {!spanId && !spansListLoading && spans.length > 0 && (
              <p style={{ fontSize: 12, color: "var(--emb-text-dim)", margin: 0 }}>
                Select a span to generate the report.
              </p>
            )}
            {!spansListLoading && spans.length === 0 && (
              <p style={{ fontSize: 12, color: "var(--yellow)", margin: 0 }}>
                No spans available. Create a span with progress targets first.
              </p>
            )}
          </div>
        </CollapsibleSection>
      </div>

      {(activitiesError || reportSpanError) && (
        <div
          className="card"
          style={{ marginBottom: 16, color: "var(--red)", fontSize: 13 }}
        >
          Failed to fetch report data:{" "}
          {activitiesError?.message ?? reportSpanError?.message}
        </div>
      )}

      {hasReport && (
        <div className="fade-up card" style={{ padding: "16px 18px" }}>
          <div
            className="card-header"
            style={{ marginBottom: 12, flexWrap: "wrap", gap: 8 }}
          >
            <div>
              <div className="card-title" style={{ marginBottom: 4 }}>
                Progress tracked
              </div>
              <div style={{ fontSize: 12, color: "var(--text2)" }}>
                {reportData.spanName ?? "—"}
                {reportData.projectName ? ` · ${reportData.projectName}` : ""}{" "}
                · {from} to {to}
              </div>
              {reportData.total > 0 && (
                <div
                  style={{
                    fontSize: 11,
                    color: "var(--text3)",
                    marginTop: 6,
                    display: "flex",
                    flexWrap: "wrap",
                    gap: "4px 12px",
                  }}
                >
                  <span>{reportData.total} entries in range</span>
                  {reportData.approved > 0 && (
                    <span style={{ color: "var(--green)" }}>
                      {reportData.approved} approved
                    </span>
                  )}
                  {reportData.submitted > 0 && (
                    <span style={{ color: "#60A5FA" }}>
                      {reportData.submitted} submitted
                    </span>
                  )}
                  {reportData.rejected > 0 && (
                    <span style={{ color: "var(--red)" }}>
                      {reportData.rejected} rejected
                    </span>
                  )}
                </div>
              )}
            </div>
            <button
              type="button"
              className="btn btn-outline btn-sm"
              onClick={handleExport}
              disabled={!reportData.progressRows?.length}
            >
              Export XLSX
            </button>
          </div>

          <SpanProgressReportView
            rows={reportData.progressRows}
            spanName={reportData.spanName}
          />

          {reportData.total === 0 && (
            <p style={{ fontSize: 12, color: "var(--text3)", marginTop: 12 }}>
              No activities in this date range for the selected span.
            </p>
          )}
        </div>
      )}
    </div>
  );
}
