export default function ReadOnlyPanel({ title, rows }) {
  if (!rows?.length) return null;
  return (
    <div className="emb-data-panel">
      {title && <div className="emb-data-panel__title">{title}</div>}
      <div className="emb-data-panel__grid">
        {rows.map(([label, value]) => (
          <div key={label} className="emb-data-panel__row">
            <span>{label}</span>
            <span>{value || "—"}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
