export default function EntryLiveSummary({
  form,
  activeProject,
  activeSpan,
  activeChapter,
  distanceProgressed,
}) {
  const completedItems = form.lineItems.filter((li) => li.label);
  const photoCount = form.lineItems.reduce(
    (n, li) =>
      n +
      (li.measurements ?? []).reduce(
        (sn, m) => sn + (m.photos?.length ?? 0),
        0,
      ),
    0,
  );

  const rows = [
    ["Project", activeProject?.name, false],
    ["Span", activeSpan?.name, false],
    [
      "Route",
      activeSpan?.startPoint?.placeName && activeSpan?.endPoint?.placeName
        ? `${activeSpan.startPoint.placeName} → ${activeSpan.endPoint.placeName}`
        : null,
      false,
    ],
    [
      "Chain",
      form.activityStartChain !== "" && form.activityEndChain !== ""
        ? `${form.activityStartChain} → ${form.activityEndChain}`
        : null,
      true,
    ],
    ["Progress", distanceProgressed != null ? `${distanceProgressed} ch` : null, true],
    ["Chapter", activeChapter?.name, false],
    [
      "Items",
      completedItems.length
        ? `${completedItems.length} selected`
        : null,
      false,
    ],
    ["Photos", photoCount > 0 ? String(photoCount) : null, true],
    ["Notes", form.locationDescription || null, false],
  ].filter(([, v]) => v);

  return (
    <div
      className="emb-dossier"
      style={{ position: "sticky", top: 16, alignSelf: "flex-start" }}
    >
      <div className="emb-dossier__head">
        Entry record <span>live</span>
      </div>
      <div className="emb-dossier__body">
        {rows.length === 0 ? (
          <div
            style={{
              padding: 14,
              fontSize: 12,
              color: "#64748b",
            }}
          >
            Fields populate as you complete each section.
          </div>
        ) : (
          rows.map(([k, v, mono]) => (
            <div key={k} className="emb-dossier__row">
              <span className="emb-dossier__key">{k}</span>
              <span className={`emb-dossier__val${mono ? " emb-dossier__val--mono" : ""}`}>
                {v}
              </span>
            </div>
          ))
        )}
      </div>

      {completedItems.length > 0 && (
        <div className="emb-dossier__section">
          <div
            style={{
              fontSize: 9,
              fontWeight: 700,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
              color: "#64748b",
              marginBottom: 6,
            }}
          >
            Schedule items
          </div>
          <div className="emb-dossier__items">
            {completedItems.map((li, i) => (
              <div key={li._id}>
                <code>{String(i + 1).padStart(2, "0")}</code>
                {li.label}
                {li.code ? ` · ${li.code}` : ""}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
