import { FormField, AlertBanner, Spinner } from "../../../../components/common/index.jsx";

function EndpointCard({ label, variant, point }) {
  if (!point) return null;
  return (
    <div className={`emb-endpoint-card emb-endpoint-card--${variant}`}>
      <div className="emb-endpoint-card__label">{label}</div>
      <div className="emb-endpoint-card__place">{point.placeName || "—"}</div>
      <div className="emb-endpoint-card__chain">
        Chain {point.chainNumber ?? "—"}
      </div>
    </div>
  );
}

export default function StepSpan({
  form,
  set,
  spans,
  spansLoading,
  spansError,
  activeSpan,
  onSpanChange,
  distanceProgressed,
  deepLinkSpanId = "",
}) {
  const spanStart = activeSpan?.startPoint?.chainNumber;
  const spanEnd = activeSpan?.endPoint?.chainNumber;
  const selectValue = form.spanId || deepLinkSpanId || "";

  return (
    <div>
      <FormField label="Span" required description="Select the span within this project">
        {spansLoading && spans.length === 0 ? (
          <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 0" }}>
            <Spinner size={16} />
            <span style={{ fontSize: "var(--emb-font-sm)", color: "var(--emb-text-muted)" }}>
              Loading spans…
            </span>
          </div>
        ) : spansError ? (
          <AlertBanner type="error" message={`Failed to load spans: ${spansError.message}`} />
        ) : spans.length === 0 ? (
          <AlertBanner type="info" message="No spans found for this project." />
        ) : (
          <select
            className="form-control"
            value={selectValue}
            onChange={(e) => onSpanChange(e.target.value)}
          >
            <option value="">Select span…</option>
            {spans.map((s) => (
              <option key={s._id ?? s.id} value={s._id ?? s.id}>
                {s.name}
              </option>
            ))}
          </select>
        )}
      </FormField>

      {activeSpan && (
        <>
          <div className="emb-endpoint-grid">
            <EndpointCard label="Start point" variant="start" point={activeSpan.startPoint} />
            <EndpointCard label="End point" variant="end" point={activeSpan.endPoint} />
          </div>

          <div
            style={{
              fontSize: "var(--emb-font-xs)",
              fontWeight: 700,
              letterSpacing: "0.1em",
              textTransform: "uppercase",
              color: "var(--emb-text-muted)",
              marginBottom: 8,
            }}
          >
            Activity extent (chain)
          </div>
          <div className="form-row" style={{ maxWidth: 420 }}>
            <FormField label="From" required>
              <input
                className="form-control"
                type="number"
                step="0.001"
                value={form.activityStartChain}
                onChange={(e) => set("activityStartChain", e.target.value)}
                placeholder={spanStart != null ? String(spanStart) : ""}
              />
            </FormField>
            <FormField label="To" required>
              <input
                className="form-control"
                type="number"
                step="0.001"
                value={form.activityEndChain}
                onChange={(e) => set("activityEndChain", e.target.value)}
                placeholder={spanEnd != null ? String(spanEnd) : ""}
              />
            </FormField>
          </div>
          {distanceProgressed != null && (
            <div className="emb-chain-progress">
              Progress within span: {distanceProgressed} chain
            </div>
          )}

          <FormField label="Location notes" description="Optional site reference">
            <textarea
              className="form-control"
              value={form.locationDescription}
              onChange={(e) => set("locationDescription", e.target.value)}
              placeholder="e.g. Up Main Line, outer yard section"
              rows={2}
              style={{ resize: "none" }}
            />
          </FormField>
        </>
      )}
    </div>
  );
}
