import { Fragment, useState } from "react";
import PhotoThumb from "../../../../components/common/photoThumb.jsx";
import { formatMeasurementDisplay } from "../../../../utils/progressReport.js";

const STATUS_COLORS = {
  APPROVED: "var(--green)",
  SUBMITTED: "#60A5FA",
  REJECTED: "var(--red)",
  DRAFT: "var(--text2)",
};

const thStyle = {
  padding: "8px 12px",
  textAlign: "left",
  fontSize: 11,
  fontWeight: 600,
  color: "var(--text2)",
  borderBottom: "1px solid var(--border)",
  whiteSpace: "nowrap",
  background: "rgba(255,255,255,.02)",
};

const tdStyle = {
  padding: "10px 12px",
  fontSize: 12,
  borderBottom: "1px solid var(--border)",
  color: "var(--text)",
  verticalAlign: "middle",
};

function ProgressBar({ pct, color }) {
  const barColor =
    pct >= 100 ? "var(--green)" : pct >= 60 ? color : "var(--yellow)";
  return (
    <div
      style={{
        height: 6,
        background: "rgba(255,255,255,.08)",
        borderRadius: 3,
        overflow: "hidden",
        marginTop: 4,
        minWidth: 80,
      }}
    >
      <div
        style={{
          width: `${Math.min(100, pct)}%`,
          height: "100%",
          background: barColor,
          borderRadius: 3,
          transition: "width .4s",
        }}
      />
    </div>
  );
}

function measurementShownInMatches(m, lineItemId, matches) {
  const lid = lineItemId != null ? String(lineItemId) : "";
  return matches.some((x) => {
    const xid = x.lineItemId != null ? String(x.lineItemId) : "";
    return xid === lid && x.measurement?.label === m.label;
  });
}

function MeasurementDetail({ m, highlight }) {
  const hasPhotos = (m.photos ?? []).length > 0;
  return (
    <div
      style={{
        padding: "10px 12px",
        background: highlight
          ? "rgba(244,160,28,.08)"
          : "rgba(255,255,255,.03)",
        border: `1px solid ${highlight ? "rgba(244,160,28,.35)" : "var(--border)"}`,
        borderRadius: 8,
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          gap: 12,
          fontSize: 13,
        }}
      >
        <span style={{ color: "var(--text2)" }}>
          {m.label}
          {m.unit ? ` (${m.unit})` : ""}
          {highlight ? (
            <span
              style={{ color: "var(--accent)", marginLeft: 6, fontSize: 11 }}
            >
              tracked
            </span>
          ) : null}
        </span>
        <span style={{ fontWeight: 700, color: "var(--text)" }}>
          {formatMeasurementDisplay(m)}
        </span>
      </div>
      {hasPhotos && (
        <div
          style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 10 }}
        >
          {m.photos.map((photo, i) => (
            <PhotoThumb key={photo._id ?? photo.url ?? i} photo={photo} />
          ))}
        </div>
      )}
    </div>
  );
}

function ActivityDetailPanel({ contributor, targetLabel, unit }) {
  const {
    activityId,
    status,
    createdAt,
    updatedAt,
    createdBy,
    locationDescription,
    delta,
    matches,
    lineItems,
  } = contributor;
  const statusColor = STATUS_COLORS[status] ?? "var(--text2)";

  const lineItemsWithOtherMeasurements = lineItems
    .map((li) => ({
      li,
      measurements: (li.measurements ?? []).filter(
        (m) => !measurementShownInMatches(m, li._id, matches),
      ),
    }))
    .filter(({ measurements }) => measurements.length > 0);

  return (
    <div
      style={{
        padding: 14,
        background: "rgba(255,255,255,.02)",
        border: "1px solid var(--border)",
        borderRadius: 8,
        marginTop: 8,
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          flexWrap: "wrap",
          gap: 8,
          marginBottom: 12,
        }}
      >
        <div>
          <div style={{ fontSize: 12, fontWeight: 700, color: "var(--text)" }}>
            Entry #{String(activityId).slice(-6)}
          </div>
          <div style={{ fontSize: 11, color: "var(--text2)", marginTop: 4 }}>
            {createdAt ? new Date(createdAt).toLocaleString("en-IN") : "—"}
            {updatedAt && updatedAt !== createdAt && (
              <span>
                {" "}
                · updated {new Date(updatedAt).toLocaleString("en-IN")}
              </span>
            )}
          </div>
          {createdBy?.name && (
            <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 2 }}>
              By {createdBy.name}
            </div>
          )}
          {locationDescription && (
            <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 2 }}>
              📍 {locationDescription}
            </div>
          )}
        </div>
        <div style={{ textAlign: "right" }}>
          <span
            style={{
              fontSize: 11,
              fontWeight: 700,
              color: statusColor,
              display: "inline-block",
              marginBottom: 6,
            }}
          >
            {status}
          </span>
          <div
            style={{ fontSize: 14, fontWeight: 700, color: "var(--accent)" }}
          >
            +{delta.toLocaleString("en-IN")}
            {unit ? ` ${unit}` : ""}
          </div>
          <div style={{ fontSize: 10, color: "var(--text3)" }}>
            {targetLabel}
          </div>
        </div>
      </div>

      <div
        style={{
          fontSize: 11,
          fontWeight: 600,
          color: "var(--text2)",
          marginBottom: 8,
        }}
      >
        Tracked measurement on this entry
      </div>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 8,
          marginBottom: 14,
        }}
      >
        {matches.map((match, i) => (
          <MeasurementDetail
            key={`${match.lineItemId}-${match.measurement.label}-${i}`}
            m={match.measurement}
            highlight
          />
        ))}
      </div>

      {lineItemsWithOtherMeasurements.length > 0 && (
        <>
          <div
            style={{
              fontSize: 11,
              fontWeight: 600,
              color: "var(--text2)",
              marginBottom: 8,
              paddingTop: 12,
              borderTop: "1px solid var(--border)",
            }}
          >
            Other measurements on this entry
          </div>
          {lineItemsWithOtherMeasurements.map(({ li, measurements }, idx) => (
            <div
              key={li._id ?? idx}
              style={{
                marginBottom: 12,
                paddingBottom: 12,
                borderBottom:
                  idx < lineItemsWithOtherMeasurements.length - 1
                    ? "1px solid var(--border2)"
                    : "none",
              }}
            >
              <div style={{ fontSize: 12, fontWeight: 600, marginBottom: 8 }}>
                {li.label ?? "Line item"} {li.code ? `· ${li.code}` : ""}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {measurements.map((m, mi) => (
                  <MeasurementDetail key={m._id ?? mi} m={m} highlight={false} />
                ))}
              </div>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

function ContributorsTable({ row, openActivityId, setOpenActivityId }) {
  const unit = row.unit ?? "";
  const targetLabel = `${row.itemLabel} · ${row.measurementLabel}`;
  const colCount = 6;

  if (!row.contributors.length) {
    return (
      <tr>
        <td
          colSpan={colCount}
          style={{ ...tdStyle, color: "var(--text3)", fontSize: 12 }}
        >
          No activities in this date range recorded progress for this
          measurement.
        </td>
      </tr>
    );
  }

  return (
    <>
      {row.contributors.map((c) => {
        const isOpen = openActivityId === c.activityId;
        const statusColor = STATUS_COLORS[c.status] ?? "var(--text2)";
        return (
          <Fragment key={c.activityId}>
            <tr
              style={{
                background: isOpen ? "rgba(244,160,28,.06)" : "transparent",
              }}
            >
              <td style={{ ...tdStyle, fontSize: 11 }}>
                #{String(c.activityId).slice(-6)}
              </td>
              <td style={tdStyle}>
                {c.createdAt
                  ? new Date(c.createdAt).toLocaleString("en-IN")
                  : "—"}
              </td>
              <td
                style={{ ...tdStyle, fontWeight: 700, color: "var(--accent)" }}
              >
                +{c.delta.toLocaleString("en-IN")}
                {unit ? ` ${unit}` : ""}
              </td>
              <td style={{ ...tdStyle, color: statusColor, fontWeight: 600 }}>
                {c.status}
              </td>
              <td style={{ ...tdStyle, color: "var(--text2)" }}>
                {c.createdBy?.name ?? "—"}
              </td>
              <td style={tdStyle}>
                <button
                  type="button"
                  className="btn btn-outline btn-sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    setOpenActivityId(isOpen ? null : c.activityId);
                  }}
                >
                  {isOpen ? "Hide" : "Details"}
                </button>
              </td>
            </tr>
            {isOpen && (
              <tr key={`${c.activityId}-detail`}>
                <td colSpan={colCount} style={{ ...tdStyle, paddingTop: 0 }}>
                  <ActivityDetailPanel
                    contributor={c}
                    targetLabel={targetLabel}
                    unit={unit}
                  />
                </td>
              </tr>
            )}
          </Fragment>
        );
      })}
    </>
  );
}

function TargetProgressTable({ rows }) {
  const [expandedKey, setExpandedKey] = useState(null);
  const [openActivityId, setOpenActivityId] = useState(null);

  const toggleRow = (key) => {
    setExpandedKey((prev) => (prev === key ? null : key));
    setOpenActivityId(null);
  };

  const mainColCount = 8;

  return (
    <div className="table-wrap">
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ ...thStyle, width: 36 }} />
            <th style={thStyle}>Chapter</th>
            <th style={thStyle}>Item</th>
            <th style={thStyle}>Measurement</th>
            <th style={{ ...thStyle, textAlign: "right" }}>Target</th>
            <th style={{ ...thStyle, textAlign: "right" }}>Cumulative</th>
            <th style={{ ...thStyle, textAlign: "right" }}>Progress</th>
            <th style={{ ...thStyle, textAlign: "right" }}>Activities</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const unit = row.unit ?? "";
            const expanded = expandedKey === row.key;
            const pctColor =
              row.pct >= 100
                ? "var(--green)"
                : row.pct > 0
                  ? (row.chapterColor ?? "var(--accent)")
                  : "var(--text3)";

            return (
              <Fragment key={row.key}>
                <tr
                  onClick={() => toggleRow(row.key)}
                  style={{
                    cursor: "pointer",
                    background: expanded
                      ? "rgba(255,255,255,.04)"
                      : "transparent",
                  }}
                >
                  <td style={tdStyle}>
                    <span style={{ fontSize: 10, color: "var(--text3)" }}>
                      {expanded ? "▼" : "▶"}
                    </span>
                  </td>
                  <td style={tdStyle}>
                    <span
                      style={{
                        display: "inline-block",
                        width: 8,
                        height: 8,
                        borderRadius: "50%",
                        background: row.chapterColor,
                        marginRight: 6,
                        verticalAlign: "middle",
                      }}
                    />
                    {row.chapterName}
                  </td>
                  <td style={tdStyle}>{row.itemLabel}</td>
                  <td style={tdStyle}>
                    {row.measurementLabel}
                    {unit ? (
                      <span style={{ color: "var(--text3)" }}> ({unit})</span>
                    ) : null}
                  </td>
                  <td
                    style={{ ...tdStyle, textAlign: "right", fontWeight: 600 }}
                  >
                    {row.targetValue.toLocaleString("en-IN")}
                    {unit ? ` ${unit}` : ""}
                  </td>
                  <td
                    style={{ ...tdStyle, textAlign: "right", fontWeight: 700 }}
                  >
                    {row.achieved.toLocaleString("en-IN")}
                    {unit ? ` ${unit}` : ""}
                  </td>
                  <td style={{ ...tdStyle, textAlign: "right", minWidth: 120 }}>
                    <div
                      style={{ fontWeight: 800, color: pctColor, fontSize: 13 }}
                    >
                      {row.progress.percentLabel}
                    </div>
                    <div
                      style={{
                        fontSize: 10,
                        color: "var(--text3)",
                        marginTop: 2,
                      }}
                    >
                      {row.progress.summary}
                    </div>
                    <ProgressBar pct={row.pct} color={row.chapterColor} />
                  </td>
                  <td style={{ ...tdStyle, textAlign: "right" }}>
                    {row.entryCount}
                  </td>
                </tr>
                {expanded && (
                  <tr key={`${row.key}-activities`}>
                    <td
                      colSpan={mainColCount}
                      style={{ padding: 0, borderBottom: "none" }}
                    >
                      <div
                        style={{
                          padding: "12px 16px 16px",
                          background: "rgba(255,255,255,.02)",
                          borderBottom: "1px solid var(--border)",
                        }}
                      >
                        <div
                          style={{
                            fontSize: 11,
                            fontWeight: 600,
                            color: "var(--text2)",
                            marginBottom: 8,
                            textTransform: "uppercase",
                            letterSpacing: ".06em",
                          }}
                        >
                          Contributing activities
                        </div>
                        <table
                          style={{
                            width: "100%",
                            borderCollapse: "collapse",
                          }}
                        >
                          <thead>
                            <tr>
                              <th style={thStyle}>Entry</th>
                              <th style={thStyle}>Date / time</th>
                              <th style={{ ...thStyle, textAlign: "right" }}>
                                Amount
                              </th>
                              <th style={thStyle}>Status</th>
                              <th style={thStyle}>Submitted by</th>
                              <th style={thStyle} />
                            </tr>
                          </thead>
                          <tbody>
                            <ContributorsTable
                              row={row}
                              openActivityId={openActivityId}
                              setOpenActivityId={setOpenActivityId}
                            />
                          </tbody>
                        </table>
                      </div>
                    </td>
                  </tr>
                )}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default function SpanProgressReportView({ rows, spanName }) {
  if (!rows?.length) {
    return (
      <div style={{ fontSize: 13, color: "var(--text3)", padding: "16px 0" }}>
        {spanName
          ? `No TargetedValues configured for "${spanName}". Add progress targets when editing the span.`
          : "No progress targets configured for this span."}
      </div>
    );
  }

  return (
    <div>
      <div className="card-title" style={{ fontSize: 13, marginBottom: 12 }}>
        Progress by tracked measurement
      </div>
      <p
        style={{
          fontSize: 12,
          color: "var(--text2)",
          marginBottom: 16,
          lineHeight: 1.5,
        }}
      >
        Each row matches span targets (chapter, item, measurement) to activity
        line items. Click a row to expand contributing activities — e.g. three 1
        km entries show as 3 km / 10 km (30%).
      </p>
      <TargetProgressTable rows={rows} />
    </div>
  );
}
