const INSTRUCTIONS_ROWS = [
  ["Project structure import — instructions"],
  [""],
  ["One row = one measurement field. Repeat chapter/item columns on each row."],
  ["chapter_name / chapter_code — group rows into chapters (code preferred)."],
  ["item_label / item_code — group rows into work items within a chapter."],
  ["field_* columns — optional per row; leave blank for item-only rows (no fields)."],
  ["field_type — number | text | select | multiselect | boolean | table | time | phone"],
  ["field_options — for select/multiselect, separate options with | (pipe)"],
  ["requires_photo — yes / no / true / false / 1 / 0"],
  ["fixed_number / fixed_text — optional constant values for number/text fields"],
  ["chapter_color — hex color e.g. #3B82F6; leave blank for auto color"],
];

function normalizeHeader(h) {
  return String(h ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "_");
}

function slugKey(label) {
  return String(label)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "_")
    .replace(/[^a-z0-9_]/g, "");
}

function parseBool(val) {
  if (val === undefined || val === null || val === "") return false;
  const s = String(val).trim().toLowerCase();
  return s === "yes" || s === "y" || s === "true" || s === "1";
}

function parseOptions(val) {
  if (val === undefined || val === null || val === "") return [];
  return String(val)
    .split("|")
    .map((o) => o.trim())
    .filter(Boolean);
}

function parseNumber(val) {
  if (val === undefined || val === null || val === "") return undefined;
  const n = Number(val);
  return Number.isFinite(n) ? n : undefined;
}

function chapterKey(row) {
  const code = String(row.chapter_code ?? "").trim();
  const name = String(row.chapter_name ?? "").trim();
  return code || name || "__unnamed_chapter__";
}

function itemKey(row) {
  const code = String(row.item_code ?? "").trim();
  const label = String(row.item_label ?? "").trim();
  return code || label || "__unnamed_item__";
}

function resolveColor(raw, index) {
  const c = String(raw ?? "").trim();
  if (/^#[0-9A-Fa-f]{6}$/.test(c)) return c;
  return CHAPTER_COLORS[index % CHAPTER_COLORS.length];
}

/**
 * Build chapter tree from flat sheet rows.
 * @returns {{ chapters: object[], errors: string[], rowCount: number }}
 */
export function rowsToChapters(rows) {
  const errors = [];
  const chapterMap = new Map();
  let chapterIndex = 0;

  rows.forEach((raw, i) => {
    const rowNum = i + 2;
    const chName = String(raw.chapter_name ?? "").trim();
    const chCode = String(raw.chapter_code ?? "").trim();
    const itLabel = String(raw.item_label ?? "").trim();
    const itCode = String(raw.item_code ?? "").trim();
    const fieldLabel = String(raw.field_label ?? "").trim();

    if (!chName && !chCode) {
      errors.push(`Row ${rowNum}: chapter_name or chapter_code is required`);
      return;
    }
    if (!itLabel && !itCode) {
      errors.push(`Row ${rowNum}: item_label or item_code is required`);
      return;
    }

    const ck = chapterKey(raw);
    let chapter = chapterMap.get(ck);
    if (!chapter) {
      chapter = {
        ...newChapter(),
        name: chName,
        code: chCode.toUpperCase(),
        color: resolveColor(raw.chapter_color, chapterIndex++),
        items: [],
        _itemMap: new Map(),
      };
      chapterMap.set(ck, chapter);
    } else {
      if (chName) chapter.name = chName;
      if (chCode) chapter.code = chCode.toUpperCase();
      if (raw.chapter_color) chapter.color = resolveColor(raw.chapter_color, 0);
    }

    const ik = itemKey(raw);
    let item = chapter._itemMap.get(ik);
    if (!item) {
      item = {
        ...newItem(),
        label: itLabel,
        code: itCode.toUpperCase(),
        description: String(raw.item_description ?? "").trim(),
        measurements: [],
      };
      chapter._itemMap.set(ik, item);
      chapter.items.push(item);
    } else {
      if (itLabel) item.label = itLabel;
      if (itCode) item.code = itCode.toUpperCase();
      if (raw.item_description) item.description = String(raw.item_description).trim();
    }

    if (!fieldLabel && !String(raw.field_key ?? "").trim()) return;

    const m = newMeasurement();
    m.label = fieldLabel;
    m.key = String(raw.field_key ?? "").trim() || slugKey(fieldLabel);
    m.unit = String(raw.field_unit ?? "").trim();

    let type = String(raw.field_type ?? "number").trim().toLowerCase();
    if (!VALID_FIELD_TYPES.has(type)) {
      errors.push(
        `Row ${rowNum}: invalid field_type "${raw.field_type}" (using number)`,
      );
      type = "number";
    }
    m.type = type;
    m.options = parseOptions(raw.field_options);
    m.billingRate = parseNumber(raw.billing_rate);
    m.targetValue = parseNumber(raw.target_value);
    m.requiresPhoto = parseBool(raw.requires_photo);

    const fixedNum = parseNumber(raw.fixed_number);
    if (fixedNum !== undefined) m.fixedNumber = fixedNum;
    const fixedTxt = String(raw.fixed_text ?? "").trim();
    if (fixedTxt) m.fixedText = fixedTxt;

    item.measurements.push(m);
  });

  const chapters = [...chapterMap.values()].map((ch) => {
    const { _itemMap, ...rest } = ch;
    return rest;
  });

  if (!chapters.length && !errors.length) {
    errors.push("No data rows found. Fill in chapter and item columns.");
  }

  return { chapters, errors, rowCount: rows.length };
}

export function parseExcelFile(arrayBuffer) {
  const wb = XLSX.read(arrayBuffer, { type: "array" });
  const sheetName =
    wb.SheetNames.find((n) => n.toLowerCase() === "project_structure") ||
    wb.SheetNames[0];
  const sheet = wb.Sheets[sheetName];
  if (!sheet) {
    return { chapters: [], errors: ["Workbook has no readable sheets."], rowCount: 0 };
  }

  const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
  if (matrix.length < 2) {
    return {
      chapters: [],
      errors: ["Sheet is empty. Use the template and add at least one data row."],
      rowCount: 0,
    };
  }

  const headers = matrix[0].map(normalizeHeader);
  const rows = matrix.slice(1).filter((row) =>
    row.some((cell) => String(cell ?? "").trim() !== ""),
  );

  const objects = rows.map((row) => {
    const obj = {};
    headers.forEach((h, i) => {
      if (h) obj[h] = row[i];
    });
    return obj;
  });

  return rowsToChapters(objects);
}

export function downloadProjectTemplate(filename = "project-structure-template.xlsx") {
  const wb = XLSX.utils.book_new();

  const dataSheet = XLSX.utils.aoa_to_sheet([TEMPLATE_HEADERS, ...EXAMPLE_ROWS]);
  dataSheet["!cols"] = TEMPLATE_HEADERS.map(() => ({ wch: 18 }));
  XLSX.utils.book_append_sheet(wb, dataSheet, "Project_Structure");

  const instrSheet = XLSX.utils.aoa_to_sheet(INSTRUCTIONS_ROWS);
  instrSheet["!cols"] = [{ wch: 72 }];
  XLSX.utils.book_append_sheet(wb, instrSheet, "Instructions");

  XLSX.writeFile(wb, filename);
}
