import { gql } from '@apollo/client';
import { PRESETS } from './fields.js';

export { PRESETS, pick, F } from './fields.js';

// ─────────────────────────────────────────────
// Builders (components pass selection at call time)
// ─────────────────────────────────────────────

const docCache = new Map();

/**
 * Compose operation shell + field selection + optional fragments.
 * OPS strings end at `fieldName(args)` — the opening `{` on the root selection set is already in OPS.
 * We add `{ selection }` for the field, then `}` to close the operation.
 */
function composeDocuments(operation, selection, fragments) {
  const flat = fragments.flat();
  // OPS ends at rootField(args); first "{" is the operation selection set (in OPS).
  // We add "{ selection }" for the field, then "}" to close the operation selection set.
  const base = gql`
    ${operation} {
      ${selection}
    }
    }
  `;
  if (!flat.length) return base;
  return flat.reduce(
    (doc, fragment) => gql`
      ${doc}
      ${fragment}
    `,
    base,
  );
}

/** @returns {import('@apollo/client').DocumentNode} */
export const buildQuery = (operation, selection, ...fragments) => {
  const flat = fragments.flat();
  const key = `Q|${operation}|${selection}|${flat.map((f) => f?.loc?.source?.body ?? '').join('::')}`;
  if (!docCache.has(key)) {
    docCache.set(key, composeDocuments(operation, selection, flat));
  }
  return docCache.get(key);
};

/** @returns {import('@apollo/client').DocumentNode} */
export const buildMutation = (operation, fields = '_id') => {
  if (fields == null) return gql`${operation}`;
  // Mutations: operation already contains "{ rootField(args)" — same brace rules as queries
  return gql`
    ${operation} {
      ${fields}
    }
    }
  `;
};

const paginated = (dataFields, paginationFields = 'page limit totalPages totalDocuments') =>
  `data {
      ${dataFields}
    }
    PaginationMetaData {
      ${paginationFields}
    }`;

// ─────────────────────────────────────────────
// Operation shells (no fixed selection)
// ─────────────────────────────────────────────

const OPS = {
  login: `mutation Public($email: String!, $password: String!) { login(email: $email, password: $password)`,

  users: {
    list: `query ListUsers(
      $page: Int $limit: Int $projects: [ID] $isActive: Boolean
      $includeSelf: Boolean $role: String
    ) { users(
      page: $page limit: $limit projects: $projects
      isActive: $isActive includeSelf: $includeSelf role: $role
    )`,
    get: 'query GetUser($id: ID!) { user(id: $id)',
    create: 'mutation CreateUser($userInput: UserInput!) { createUser(userInput: $userInput)',
    update: 'mutation UpdateUser($id: ID!, $userInput: UserInput) { updateUser(_id: $id, userInput: $userInput)',
    delete: 'mutation DeleteUser($id: ID!) { deleteUser(id: $id) }',
  },

  projects: {
    list: 'query ListProjects($page: Int, $limit: Int) { projects(page: $page, limit: $limit)',
    get: 'query GetProject($id: ID!) { project(id: $id)',
    create: 'mutation CreateProject($projectInput: ProjectInput!) { createProject(projectInput: $projectInput)',
    update: 'mutation UpdateProject($id: ID!, $projectInput: ProjectInput!) { updateProject(_id: $id, projectInput: $projectInput)',
  },

  spans: {
    facets: gql`
      query spansFacet(
        $status: String $projects: [ID]
        $startPoints: [String] $endPoints: [String]
      ) {
        spansFacet(
          status: $status projects: $projects
          startPoints: $startPoints endPoints: $endPoints
        )
      }
    `,
    list: `query getSpans(
      $page: Int $limit: Int $status: String $projects: [ID]
      $startPoints: [String] $endPoints: [String]
    ) { spans(
      page: $page limit: $limit status: $status projects: $projects
      startPoints: $startPoints endPoints: $endPoints
    )`,
    get: 'query getSpan($id: ID!) { span(_id: $id)',
    create: 'mutation createSpan($spanInput: SpanInput!) { createSpan(spanInput: $spanInput)',
    update: 'mutation UpdateSpan($id: ID!, $spanInput: SpanInput!) { updateSpan(_id: $id, spanInput: $spanInput)',
    addStaff: 'mutation AddStaff($id: ID!, $userId: ID!) { addStaff(_id: $id, userID: $userId)',
    removeStaff: 'mutation RemoveStaff($id: ID!, $userId: ID!) { removeStaff(_id: $id, userID: $userId)',
  },

  activities: {
    facets: gql`
      query activitiesFacet(
        $status: String $span: [ID] $project: [ID] $createdBy: [ID]
      ) {
        activitiesFacet(
          status: $status span: $span project: $project createdBy: $createdBy
        )
      }
    `,
    list: `query activities(
      $page: Int $limit: Int $status: String $span: [ID] $project: [ID]
      $createdBy: [ID] $fromDate: DateTime $toDate: DateTime
    ) { activities(
      page: $page limit: $limit status: $status span: $span project: $project
      createdBy: $createdBy fromDate: $fromDate toDate: $toDate
    )`,
  },
};

// ─────────────────────────────────────────────
// FRAGMENTS (optional — use via spread in `fields`)
// ─────────────────────────────────────────────

export const USER_FRAGMENT = gql`
  fragment UserFields on User {
    _id name email role designation isActive scopes
    projects { _id name code }
    spans { _id name status project { _id name } }
  }
`;

export const PAGINATION_FRAGMENT = gql`
  fragment PaginationFields on PaginationMetaData {
    page limit totalPages totalDocuments
  }
`;

export const ITEM_FRAGMENT = gql`
  fragment ItemFields on Item {
    _id label code description measurements
  }
`;

export const CHAPTER_FRAGMENT = gql`
  fragment ChapterFields on Chapter {
    _id name color
    items { ...ItemFields }
  }
  ${ITEM_FRAGMENT}
`;

export const PROJECT_FRAGMENT = gql`
  fragment ProjectFields on Project {
    _id name code description status
    chapters { ...ChapterFields }
    createdAt updatedAt
    Vault { allotedBudjet spentBudjet logs }
    cumulativeProgress
  }
  ${CHAPTER_FRAGMENT}
`;

export const CHAPTER_ON_SPAN_FRAGMENT = gql`
  fragment ChapterOnSpanFields on Chapter {
    _id name code color
    items { _id label code description measurements }
  }
`;

export const SPAN_FRAGMENT = gql`
  fragment SpanFields on Span {
    _id name status createdAt updatedAt
    project { _id name status code }
    startPoint { placeName chainNumber pointLocation { type coordinates } }
    endPoint { placeName chainNumber pointLocation { type coordinates } }
    chapters { ...ChapterOnSpanFields }
    TargetedValues { chapterId itemId measurementLabel targetValue }
    Vault { allotedBudjet spentBudjet logs }
    staff { _id name designation }
  }
  ${CHAPTER_ON_SPAN_FRAGMENT}
`;

/** Span list table — no designation on staff (matches old spanTable preset). */
export const SPAN_LIST_FRAGMENT = gql`
  fragment SpanListFields on Span {
    _id name status createdAt updatedAt
    project { _id name status code }
    startPoint { placeName chainNumber pointLocation { type coordinates } }
    endPoint { placeName chainNumber pointLocation { type coordinates } }
    chapters { ...ChapterOnSpanFields }
    TargetedValues { chapterId itemId measurementLabel targetValue }
    Vault { allotedBudjet spentBudjet logs }
    staff { _id name }
  }
  ${CHAPTER_ON_SPAN_FRAGMENT}
`;

/** Progress report span rows */
export const SPAN_REPORT_FRAGMENT = gql`
  fragment SpanReportFields on Span {
    _id name
    project {
      _id name
      chapters { ...ChapterOnSpanFields }
    }
    chapters { ...ChapterOnSpanFields }
    TargetedValues { chapterId itemId measurementLabel targetValue }
  }
  ${CHAPTER_ON_SPAN_FRAGMENT}
`;

// Fragment bundles for spread selections
export const FRAGMENTS = {
  user: [USER_FRAGMENT],
  pagination: [PAGINATION_FRAGMENT],
  project: [PROJECT_FRAGMENT, PAGINATION_FRAGMENT],
  projectSingle: [PROJECT_FRAGMENT],
  /** `PRESETS.projectPicker` — chapters { ...ChapterFields } without full ProjectFields */
  projectPicker: [CHAPTER_FRAGMENT, PAGINATION_FRAGMENT],
  span: [SPAN_FRAGMENT, PAGINATION_FRAGMENT],
  spanTable: [SPAN_LIST_FRAGMENT, PAGINATION_FRAGMENT],
  spanReport: [SPAN_REPORT_FRAGMENT, PAGINATION_FRAGMENT],
  spanSingle: [SPAN_FRAGMENT],
  chapterOnSpan: [CHAPTER_ON_SPAN_FRAGMENT],
};

/** @deprecated Prefer `FRAGMENTS.projectPicker` */
export const PROJECT_PICKER_FRAGMENTS = FRAGMENTS.projectPicker;

function resolveSpanFragments(fields) {
  if (fields.includes('...SpanFields')) return FRAGMENTS.span;
  if (fields.includes('...SpanListFields')) return FRAGMENTS.spanTable;
  if (fields.includes('...SpanReportFields')) return FRAGMENTS.spanReport;
  if (fields.includes('...ChapterOnSpanFields')) {
    return [CHAPTER_ON_SPAN_FRAGMENT, PAGINATION_FRAGMENT];
  }
  return [PAGINATION_FRAGMENT];
}

// ─────────────────────────────────────────────
// Q — query factories (pass fields from component)
// ─────────────────────────────────────────────

export const Q = {
  auth: {
    login: (userFields = '...UserFields') =>
      buildQuery(OPS.login, `accessToken refreshToken user { ${userFields} }`, USER_FRAGMENT),
  },

  users: {
    list: (userFields = '...UserFields', { pagination = '...PaginationFields' } = {}) =>
      buildQuery(
        OPS.users.list,
        paginated(userFields, pagination),
        USER_FRAGMENT,
        PAGINATION_FRAGMENT,
      ),
    get: (userFields = '...UserFields') =>
      buildQuery(OPS.users.get, userFields, USER_FRAGMENT),
  },

  projects: {
    list: (projectFields = '...ProjectFields', opts = {}) =>
      buildQuery(
        OPS.projects.list,
        paginated(projectFields, opts.pagination ?? '...PaginationFields'),
        ...(opts.fragments ?? FRAGMENTS.project),
      ),
    get: (projectFields = '...ProjectFields') =>
      buildQuery(OPS.projects.get, projectFields, PROJECT_FRAGMENT),
  },

  spans: {
    facets: OPS.spans.facets,
    list: (spanFields = '...SpanListFields', opts = {}) =>
      buildQuery(
        OPS.spans.list,
        paginated(spanFields, opts.pagination ?? '...PaginationFields'),
        ...(opts.fragments ?? resolveSpanFragments(spanFields)),
      ),
    get: (spanFields = '...SpanFields') =>
      buildQuery(
        OPS.spans.get,
        spanFields,
        ...resolveSpanFragments(spanFields).filter((f) => f !== PAGINATION_FRAGMENT),
      ),
  },

  activities: {
    facets: OPS.activities.facets,
    list: (activityFields, opts = {}) => {
      const pagination = opts.pagination ?? '...PaginationFields';
      const fragments =
        opts.fragments ??
        (pagination.includes('...PaginationFields') ? FRAGMENTS.pagination : []);
      return buildQuery(
        OPS.activities.list,
        paginated(activityFields, pagination),
        ...fragments,
      );
    },
  },
};

// ─────────────────────────────────────────────
// M — mutation factories
// ─────────────────────────────────────────────

export const M = {
  users: {
    create: (fields = '...UserFields') =>
      buildQuery(OPS.users.create, fields, USER_FRAGMENT),
    update: (fields = '_id') => buildMutation(OPS.users.update, fields),
    delete: () => buildMutation(OPS.users.delete, null),
  },

  projects: {
    create: (fields = '_id name') => buildMutation(OPS.projects.create, fields),
    update: (fields = '_id name') => buildMutation(OPS.projects.update, fields),
  },

  spans: {
    create: (fields = '_id') => buildMutation(OPS.spans.create, fields),
    update: (fields = '_id') => buildMutation(OPS.spans.update, fields),
    addStaff: (fields = '_id') => buildMutation(OPS.spans.addStaff, fields),
    removeStaff: (fields = '_id') => buildMutation(OPS.spans.removeStaff, fields),
  },

  activities: {
    create: (fields = '_id') =>
      buildMutation(
        'mutation CreateActivity($activityInput: ActivityInput!) { createActivity(activityInput: $activityInput)',
        fields,
      ),
    updateStatus: (fields = '_id status') =>
      buildMutation(
        `mutation UpdateActivityStatus($_id: ID!, $statusUpdateInput: statusUpdateInput!) {
          updateActivityStatus(_id: $_id, statusUpdateInput: $statusUpdateInput)`,
        fields,
      ),
    update: (fields = '_id') =>
      buildMutation(
        'mutation UpdateActivity($_id: ID!, $lineItems: JSON) { updateActivity(_id: $_id, lineItems: $lineItems)',
        fields,
      ),
  },
};

