import { getChapterName } from "./helpers.js";

const API_ORIGIN = "https://kbbackend-production.up.railway.app";

/** Resolve photo URL (absolute, data URL, or path on API host). */
export function resolvePhotoUrl(photo) {
  if (!photo) return "";
  const raw = photo.url ?? photo.imageUrl ?? photo.path ?? "";
  if (!raw || typeof raw !== "string") return "";
  if (/^(https?:|data:|blob:)/i.test(raw)) return raw;
  if (raw.startsWith("/")) return `${API_ORIGIN}${raw}`;
  return `${API_ORIGIN}/${raw}`;
}

export function latLngKey(latlng, precision = 5) {
  return `${Number(latlng[0]).toFixed(precision)},${Number(latlng[1]).toFixed(precision)}`;
}

/** Group markers that share the same coordinates (within precision). */
export function groupMarkersByLatLng(markers, precision = 5) {
  const map = new Map();
  for (const m of markers) {
    const key = latLngKey(m.latlng, precision);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(m);
  }
  return [...map.values()].map((items) => ({
    latlng: items[0].latlng,
    items,
  }));
}

/** Span endpoints are stored as [latitude, longitude]. */
export function spanPointToLatLng(point) {
  const coords = point?.pointLocation?.coordinates;
  if (!Array.isArray(coords) || coords.length < 2) return null;
  const lat = Number(coords[0]);
  const lng = Number(coords[1]);
  if (!isValidLatLng(lat, lng)) return null;
  if (Math.abs(lat) > 90) return [lng, lat];
  return [lat, lng];
}

/** Measurement photos use GeoJSON [longitude, latitude]. */
export function photoToLatLng(photo) {
  const coords = photo?.pointLocation?.coordinates;
  if (!Array.isArray(coords) || coords.length < 2) return null;
  const lng = Number(coords[0]);
  const lat = Number(coords[1]);
  if (!isValidLatLng(lat, lng)) return null;
  return [lat, lng];
}

function isValidLatLng(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
  if (Math.abs(lat) < 1e-6 && Math.abs(lng) < 1e-6) return false;
  return Math.abs(lat) <= 90 && Math.abs(lng) <= 180;
}

/** @returns {{ type: 'start'|'end', latlng, span, point, label }[]} */
export function collectSpanEndpointMarkers(spans = []) {
  const markers = [];
  for (const span of spans) {
    const start = spanPointToLatLng(span.startPoint);
    if (start) {
      markers.push({
        type: "start",
        latlng: start,
        span,
        point: span.startPoint,
        label: span.startPoint?.placeName ?? "Start",
      });
    }
    const end = spanPointToLatLng(span.endPoint);
    if (end) {
      markers.push({
        type: "end",
        latlng: end,
        span,
        point: span.endPoint,
        label: span.endPoint?.placeName ?? "End",
      });
    }
  }
  return markers;
}

/** @returns photo marker objects from activity lineItems */
export function collectPhotoMarkers(activities = []) {
  const markers = [];
  for (const activity of activities) {
    const lineItems = activity.lineItems ?? [];
    for (const li of lineItems) {
      for (const m of li.measurements ?? []) {
        for (const photo of m.photos ?? []) {
          const latlng = photoToLatLng(photo);
          if (!latlng) continue;
          markers.push({
            latlng,
            photo,
            activity,
            lineItem: li,
            measurement: m,
          });
        }
      }
    }
  }
  return markers;
}

export const GIS_STATUS_COLORS = {
  APPROVED: "#22C55E",
  SUBMITTED: "#60A5FA",
  REJECTED: "#EF4444",
  RETURNED: "#A855F7",
  DRAFT: "#94A3B8",
  PENDING: "#FBBF24",
};

export function escapeHtml(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function spanEndpointPopupHtml(marker) {
  const { span, type, point, label } = marker;
  const kind = type === "start" ? "Start point" : "End point";
  const [lat, lng] = marker.latlng;
  return `
    <div style="font-family:sans-serif;min-width:200px;padding:4px;line-height:1.45">
      <div style="font-size:10px;font-weight:700;text-transform:uppercase;color:${type === "start" ? "#22C55E" : "#EF4444"};margin-bottom:4px">${kind}</div>
      <strong style="font-size:13px">${escapeHtml(span.name)}</strong><br/>
      <span style="font-size:11px;color:#666">${escapeHtml(span.project?.name ?? "")}</span><br/>
      <span style="font-size:12px">${escapeHtml(label)}</span>
      ${point?.chainNumber != null ? `<br/><span style="font-size:11px">Chain ${escapeHtml(point.chainNumber)}</span>` : ""}
      <br/><span style="font-size:10px;color:#888;font-family:monospace">${lat.toFixed(5)}, ${lng.toFixed(5)}</span>
    </div>
  `;
}

function popupStyles() {
  return {
    root: "font-family:var(--font-body, sans-serif);min-width:220px;max-width:320px;max-height:280px;overflow-y:auto;padding:2px 4px;line-height:1.45",
    heading: "font-size:11px;font-weight:700;color:#64748b;margin:0 0 8px;text-transform:uppercase;letter-spacing:.05em",
    item: "padding:8px 0;border-bottom:1px solid rgba(128,128,128,.25)",
    itemLast: "padding:8px 0",
    thumb: "width:56px;height:56px;object-fit:cover;border-radius:6px;border:1px solid rgba(128,128,128,.3);flex-shrink:0",
    btn: "margin-top:6px;padding:4px 10px;font-size:11px;font-weight:600;border-radius:4px;border:1px solid #F4A01C;background:rgba(244,160,28,.15);color:#E8730A;cursor:pointer;font-family:inherit",
  };
}

/** Build popup DOM for one or more photo markers at the same location. */
export function buildPhotoPopupElement(group, onViewPhoto) {
  const s = popupStyles();
  const root = document.createElement("div");
  root.className = "gis-photo-popup";
  root.setAttribute("style", s.root);

  if (group.length > 1) {
    const heading = document.createElement("div");
    heading.setAttribute("style", s.heading);
    heading.textContent = `${group.length} photos at this location`;
    root.appendChild(heading);
  }

  group.forEach((marker, idx) => {
    const { activity, lineItem, measurement, photo } = marker;
    const color = GIS_STATUS_COLORS[activity.status] ?? "#94A3B8";
    const chapter = getChapterName(activity.chapter);
    const url = resolvePhotoUrl(photo);
    const isLast = idx === group.length - 1;

    const row = document.createElement("div");
    row.setAttribute("style", isLast ? s.itemLast : s.item);

    const flex = document.createElement("div");
    flex.setAttribute("style", "display:flex;gap:10px;align-items:flex-start");

    if (url) {
      const img = document.createElement("img");
      img.src = url;
      img.alt = photo.caption || lineItem.label || "Photo";
      img.setAttribute("style", s.thumb);
      img.onerror = () => {
        img.style.display = "none";
      };
      flex.appendChild(img);
    }

    const text = document.createElement("div");
    text.setAttribute("style", "flex:1;min-width:0");
    text.innerHTML = `
      <strong style="font-size:13px;display:block">${escapeHtml(lineItem.label ?? "Line item")}</strong>
      <span style="font-size:11px;color:#666">${escapeHtml(chapter)} · ${escapeHtml(measurement.label ?? "")}</span><br/>
      <span style="color:${color};font-weight:600;font-size:12px">${escapeHtml(activity.status)}</span><br/>
      <span style="font-size:11px">Span: ${escapeHtml(activity.span?.name ?? "—")}</span>
      ${activity.createdBy?.name ? `<br/><span style="font-size:11px">By ${escapeHtml(activity.createdBy.name)}</span>` : ""}
      ${photo.caption ? `<br/><span style="font-size:11px;font-style:italic">${escapeHtml(photo.caption)}</span>` : ""}
    `;
    flex.appendChild(text);
    row.appendChild(flex);

    if (url && typeof onViewPhoto === "function") {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = "View full photo";
      btn.setAttribute("style", s.btn);
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        onViewPhoto(photo);
      });
      row.appendChild(btn);
    }

    root.appendChild(row);
  });

  return root;
}

/** Build popup DOM for span endpoint markers at the same location. */
export function buildSpanGroupPopupElement(group) {
  const s = popupStyles();
  const root = document.createElement("div");
  root.className = "gis-span-popup";
  root.setAttribute("style", s.root);

  if (group.length > 1) {
    const heading = document.createElement("div");
    heading.setAttribute("style", s.heading);
    heading.textContent = `${group.length} points at this location`;
    root.appendChild(heading);
  }

  group.forEach((marker, idx) => {
    const { span, type, point, label } = marker;
    const kind = type === "start" ? "Start point" : "End point";
    const color = type === "start" ? "#22C55E" : "#EF4444";
    const [lat, lng] = marker.latlng;
    const isLast = idx === group.length - 1;

    const row = document.createElement("div");
    row.setAttribute("style", isLast ? s.itemLast : s.item);
    row.innerHTML = `
      <div style="font-size:10px;font-weight:700;text-transform:uppercase;color:${color};margin-bottom:4px">${kind}</div>
      <strong style="font-size:13px">${escapeHtml(span.name)}</strong><br/>
      <span style="font-size:11px;color:#666">${escapeHtml(span.project?.name ?? "")}</span><br/>
      <span style="font-size:12px">${escapeHtml(label)}</span>
      ${point?.chainNumber != null ? `<br/><span style="font-size:11px">Chain ${escapeHtml(point.chainNumber)}</span>` : ""}
      <br/><span style="font-size:10px;color:#888;font-family:monospace">${lat.toFixed(5)}, ${lng.toFixed(5)}</span>
    `;
    root.appendChild(row);
  });

  return root;
}
