/** Resolve project id from span API shape (nested project or projectId). */
export function getSpanProjectId(span) {
  if (!span) return "";
  return span.project?._id ?? span.projectId ?? "";
}

/** Resolve span id from API shape (_id or id). */
export function getSpanId(span) {
  if (!span) return "";
  return span._id ?? span.id ?? "";
}

export function idsMatch(a, b) {
  if (!a || !b) return false;
  return String(a).trim() === String(b).trim();
}

/** Parse chain input for API `chinageFrom` / `chinageTo` (Float). */
export function parseChainageValue(value) {
  if (value === "" || value == null) return undefined;
  const n = parseFloat(value);
  return Number.isFinite(n) ? n : undefined;
}

export function calcDistance(startChain, endChain) {
  const start = parseFloat(startChain);
  const end = parseFloat(endChain);
  if (Number.isNaN(start) || Number.isNaN(end)) return null;
  const d = Math.abs(end - start);
  return Number.isInteger(d) ? d : parseFloat(d.toFixed(3));
}

/** Parse "Chain 100 → 200" from a stored location description. */
export function parseChainRange(locationDescription) {
  if (!locationDescription) return { start: "", end: "" };
  const match = String(locationDescription).match(
    /Chain\s+([\d.]+)\s*→\s*([\d.]+)/i,
  );
  if (!match) return { start: "", end: "" };
  return { start: match[1], end: match[2] };
}
