import { Spinner } from "../../../../components/common/index.jsx";
import ReadOnlyPanel from "./ReadOnlyPanel.jsx";

export default function StepEditProjectReadOnly({
  activeProject,
  loading,
  error,
}) {
  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 0" }}>
        <Spinner size={16} />
        <span style={{ fontSize: "var(--emb-font-sm)", color: "var(--emb-text-muted)" }}>
          Loading project…
        </span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="emb-lock-banner emb-lock-banner--warn">
        Could not load full project details.
      </div>
    );
  }

  return (
    <>
      <div className="emb-lock-banner">
        Locked — project cannot be changed when editing an entry
      </div>
      <ReadOnlyPanel
        title="Project"
        rows={[
          ["Name", activeProject?.name],
          ["Code", activeProject?.code],
          ["Status", activeProject?.status],
        ]}
      />
    </>
  );
}
