export default function CollapsibleSection({
  step,
  title,
  summary,
  isOpen,
  isComplete,
  isDisabled,
  onToggle,
  children,
}) {
  const panelClass = [
    "emb-panel",
    isOpen && "is-open",
    isComplete && "is-complete",
    isDisabled && "is-disabled",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={panelClass}>
      <button
        type="button"
        className="emb-panel__header"
        onClick={() => !isDisabled && onToggle()}
        disabled={isDisabled}
      >
        <div className="emb-panel__accent" />
        <div className="emb-panel__body-inner">
          <span className="emb-panel__step">
            {isComplete ? "OK" : String(step).padStart(2, "0")}
          </span>
          <div className="emb-panel__titles">
            <div className="emb-panel__title">{title}</div>
            {!isOpen && summary && (
              <div className="emb-panel__summary">{summary}</div>
            )}
          </div>
          <span className="emb-panel__chevron">▼</span>
        </div>
      </button>
      {isOpen && !isDisabled && (
        <div className="emb-panel__content">{children}</div>
      )}
    </div>
  );
}
