import { useState } from "react";
import MeasurementInput, {
  MeasurementColInput,
  PhotoControls,
} from "./MeasurementInput.jsx";

function isGridField(dim) {
  return (
    dim.type !== "boolean" &&
    dim.type !== "table" &&
    dim.type !== "multiselect"
  );
}

function isLengthLabel(label) {
  return /len/i.test(label ?? "");
}

function partitionMeasurements(dims) {
  const gridDims = dims.filter((d) => isGridField(d) && !d.requiresPhoto);
  const photoDims = dims.filter((d) => d.requiresPhoto);
  const boolDims = dims.filter((d) => d.type === "boolean" && !d.requiresPhoto);
  const wideDims = dims.filter(
    (d) => d.type === "table" || d.type === "multiselect",
  );

  let lengthPhotoIdx = photoDims.findIndex((d) => isLengthLabel(d.label));
  if (lengthPhotoIdx < 0 && photoDims.length) lengthPhotoIdx = 0;

  const lengthPhotoDim =
    lengthPhotoIdx >= 0 ? photoDims[lengthPhotoIdx] : null;
  const otherPhotoDims = photoDims.filter((_, i) => i !== lengthPhotoIdx);

  const sheetCols = [...gridDims, ...(lengthPhotoDim ? [lengthPhotoDim] : [])];

  return { gridDims, lengthPhotoDim, otherPhotoDims, boolDims, wideDims, sheetCols };
}

function MeasureColHeader({ dim, evidence, photos, onPhotosChange }) {
  return (
    <div className={`mb-measure-col${evidence ? " is-evidence" : ""}`}>
      <div className="mb-measure-col__label-block">
        <span className="mb-measure-col__name">{dim.label}</span>
        {dim.unit && <span className="mb-measure-col__unit">{dim.unit}</span>}
      </div>
      {evidence && onPhotosChange && (
        <div className="mb-measure-col__photo">
          <PhotoControls
            dim={dim}
            photos={photos ?? []}
            setPhotos={onPhotosChange}
            hintLabel={dim.label}
          />
        </div>
      )}
    </div>
  );
}

export default function StepMeasurements({ form, updateLine }) {
  const [activeIdx, setActiveIdx] = useState(0);
  const lineItems = form.lineItems.filter((li) => li.label);
  const li = lineItems[activeIdx];

  if (lineItems.length === 0) {
    return (
      <div style={{ padding: 20, textAlign: "center", color: "var(--emb-text-dim)", fontSize: "var(--emb-font-sm)" }}>
        No line items selected. Complete chapter &amp; line items first.
      </div>
    );
  }

  const dims = li.measurements || [];
  const { sheetCols, lengthPhotoDim, otherPhotoDims, boolDims, wideDims, gridDims } =
    partitionMeasurements(dims);

  const patchMeasurement = (dimLabel, patch) =>
    updateLine(li._id, {
      measurements: li.measurements.map((m) =>
        m.label === dimLabel ? { ...m, ...patch } : m,
      ),
    });

  return (
    <div>
      {lineItems.length > 1 && (
        <div className="mb-tabs">
          {lineItems.map((item, i) => (
            <button
              key={item._id}
              type="button"
              className={`mb-tab${i === activeIdx ? " is-active" : ""}`}
              onClick={() => setActiveIdx(i)}
            >
              {String(i + 1).padStart(2, "0")} {item.code || item.label}
            </button>
          ))}
        </div>
      )}

      <div className="mb-spec-bar">
        <div>
          <div className="mb-spec-bar__label">Work item</div>
          <div className="mb-spec-bar__value">{li.label}</div>
        </div>
        {li.code && (
          <div>
            <div className="mb-spec-bar__label">Item code</div>
            <div className="mb-spec-bar__code">{li.code}</div>
          </div>
        )}
      </div>

      {dims.length === 0 ? (
        <div style={{ fontSize: "var(--emb-font-sm)", color: "var(--emb-text-dim)" }}>
          No measurement dimensions defined for this item.
        </div>
      ) : sheetCols.length > 0 ? (
        <div className="mb-measure-sheet">
          <div className="mb-measure-sheet__head">
            {gridDims.map((dim) => (
              <MeasureColHeader key={dim._id || dim.label} dim={dim} />
            ))}
            {lengthPhotoDim && (
              <MeasureColHeader
                dim={lengthPhotoDim}
                evidence
                photos={lengthPhotoDim.photos ?? []}
                onPhotosChange={(p) =>
                  patchMeasurement(lengthPhotoDim.label, { photos: p })
                }
              />
            )}
          </div>
          <div className="mb-measure-sheet__row">
            {gridDims.map((dim) => (
              <div key={dim._id || dim.label} className="mb-measure-col">
                <MeasurementColInput
                  dim={dim}
                  value={dim.value}
                  onChange={(val) => patchMeasurement(dim.label, { value: val })}
                />
              </div>
            ))}
            {lengthPhotoDim && (
              <div className="mb-measure-col is-evidence">
                <MeasurementColInput
                  dim={lengthPhotoDim}
                  value={lengthPhotoDim.value}
                  photos={lengthPhotoDim.photos ?? []}
                  onChange={(val, photos) =>
                    patchMeasurement(lengthPhotoDim.label, { value: val, photos })
                  }
                />
              </div>
            )}
          </div>
        </div>
      ) : null}

      {(otherPhotoDims.length > 0 || boolDims.length > 0 || wideDims.length > 0) && (
        <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 12 }}>
          {otherPhotoDims.map((dim) => (
            <MeasurementInput
              key={dim._id || dim.label}
              dim={dim}
              value={dim.value}
              photos={dim?.photos ?? []}
              onChange={(val, photos) =>
                patchMeasurement(dim.label, { value: val, photos })
              }
            />
          ))}
          {boolDims.map((dim) => (
            <MeasurementInput
              key={dim._id || dim.label}
              dim={dim}
              value={dim.value}
              onChange={(val) => patchMeasurement(dim.label, { value: val })}
            />
          ))}
          {wideDims.map((dim) => (
            <MeasurementInput
              key={dim._id || dim.label}
              dim={dim}
              value={dim.value}
              onChange={(val) => patchMeasurement(dim.label, { value: val })}
            />
          ))}
        </div>
      )}
    </div>
  );
}
