import {
  FormField,
  AlertBanner,
  Spinner,
} from "../../../../components/common/index.jsx";
import ReadOnlyPanel from "./ReadOnlyPanel.jsx";

export default function StepProject({
  form,
  projects,
  projectsLoading,
  projectsError,
  activeProject,
  onProjectChange,
}) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
      <FormField label="Project" required description="Select the project for this entry">
        {projectsLoading ? (
          <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 0" }}>
            <Spinner size={16} />
            <span style={{ fontSize: 13, color: "var(--text2)" }}>Loading projects…</span>
          </div>
        ) : projectsError ? (
          <AlertBanner type="error" message={`Failed to load projects: ${projectsError.message}`} />
        ) : (
          <select
            className="form-control"
            value={form.projectId ?? ""}
            onChange={(e) => onProjectChange(e.target.value)}
            style={{ fontSize: 15 }}
          >
            <option value="">Select project…</option>
            {projects.map((p) => (
              <option key={p._id} value={p._id}>
                {p.name}
                {p.code ? ` (${p.code})` : ""}
              </option>
            ))}
          </select>
        )}
      </FormField>

      {activeProject && (
        <ReadOnlyPanel
          title="Project details"
          rows={[
            ["Name", activeProject.name],
            ["Code", activeProject.code],
            ["Status", activeProject.status],
            ["Description", activeProject.description],
          ]}
        />
      )}
    </div>
  );
}
