import * as XLSX from "xlsx";

function safeFilenamePart(s) {
  return String(s ?? "report")
    .replace(/[^\w.-]+/g, "_")
    .slice(0, 48);
}

/**
 * Export span progress report rows to XLSX (summary + contributing activities).
 */
export function exportProgressReportXlsx({
  rows = [],
  spanName,
  projectName,
  from,
  to,
}) {
  const progressSheet = [
    ["Progress report"],
    ["Span", spanName ?? ""],
    ["Project", projectName ?? ""],
    ["Period", `${from ?? ""} to ${to ?? ""}`],
    [],
    [
      "Chapter",
      "Item",
      "Measurement",
      "Unit",
      "Target",
      "Cumulative",
      "Progress",
      "Activities",
    ],
  ];

  for (const row of rows) {
    progressSheet.push([
      row.chapterName ?? "",
      row.itemLabel ?? "",
      row.measurementLabel ?? "",
      row.unit ?? "",
      row.targetValue ?? 0,
      row.achieved ?? 0,
      row.progress?.percentLabel ?? `${row.pct ?? 0}%`,
      row.entryCount ?? 0,
    ]);
  }

  const activitySheet = [
    [
      "Chapter",
      "Item",
      "Measurement",
      "Entry ID",
      "Date",
      "Status",
      "Amount",
      "Unit",
      "Submitted by",
      "Location",
    ],
  ];

  for (const row of rows) {
    for (const c of row.contributors ?? []) {
      activitySheet.push([
        row.chapterName ?? "",
        row.itemLabel ?? "",
        row.measurementLabel ?? "",
        c.activityId ?? "",
        c.createdAt
          ? new Date(c.createdAt).toLocaleString("en-IN")
          : "",
        c.status ?? "",
        c.delta ?? 0,
        row.unit ?? "",
        c.createdBy?.name ?? "",
        c.locationDescription ?? "",
      ]);
    }
  }

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(
    wb,
    XLSX.utils.aoa_to_sheet(progressSheet),
    "Progress",
  );
  if (activitySheet.length > 1) {
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.aoa_to_sheet(activitySheet),
      "Activities",
    );
  }

  const name = safeFilenamePart(spanName);
  XLSX.writeFile(wb, `progress-report-${name}-${from}-${to}.xlsx`);
}
