import { useState, useMemo } from "react";
import { PageHeader, Spinner } from "../../../components/common/index.jsx";
import "../new-entry/entryForm.css";
import CollapsibleSection from "../new-entry/components/CollapsibleSection.jsx";
import StepEditProjectReadOnly from "../new-entry/components/StepEditProjectReadOnly.jsx";
import StepEditSpanReadOnly from "../new-entry/components/StepEditSpanReadOnly.jsx";
import StepChapterItems from "../new-entry/components/StepChapterItems.jsx";
import StepMeasurements from "../new-entry/components/StepMeasurements.jsx";
import EntryLiveSummary from "../new-entry/components/EntryLiveSummary.jsx";
import useWideLayout from "../new-entry/hooks/useWideLayout.js";
import { M } from "../../../apollo/gql.js";
import { useApiMutation } from "../../../apollo/useApi.js";
import { deepClean, getChapterName, getChapterId } from "../../../utils/helpers.js";
import { addLine, removeLine, updateLine } from "../common/index.js";
import { calcDistance, parseChainRange } from "../new-entry/utils.js";

function remarksText(remarks) {
  if (!remarks) return "";
  if (Array.isArray(remarks)) {
    return remarks
      .map((r) => r.notes)
      .filter(Boolean)
      .join(" · ");
  }
  return String(remarks);
}

function locationNotesOnly(locationDescription) {
  if (!locationDescription) return "";
  const parts = String(locationDescription)
    .split(".")
    .map((p) => p.trim())
    .filter(Boolean);
  const withoutChain = parts.filter((p) => !/^Chain\s+[\d.]+\s*→/i.test(p));
  return withoutChain.join(". ");
}

export default function EditEmbEntry({
  entry,
  activeSpan,
  activeChapter,
  spanLoading,
  spanError,
  onSaved,
  onCancel,
}) {
  const wide = useWideLayout();
  const [updateEmbEntry] = useApiMutation(M.activities.update, { fields: "_id" });
  const [saving, setSaving] = useState(false);
  const chains = parseChainRange(entry.locationDescription);

  const [form, setForm] = useState(() => ({
    projectId: entry.project?._id ?? "",
    spanId: entry.span?._id ?? entry.span?.id ?? "",
    chapter: getChapterName(entry.chapter) ?? "",
    chapterId: getChapterId(entry.chapter) ?? "",
    locationDescription:
      locationNotesOnly(entry.locationDescription) || entry.locationDescription || "",
    activityStartChain:
      entry.chinageFrom != null
        ? String(entry.chinageFrom)
        : chains.start,
    activityEndChain:
      entry.chinageTo != null ? String(entry.chinageTo) : chains.end,
    lineItems: (entry.lineItems ?? []).map((li) => ({
      ...li,
      _id: li._id ?? crypto.randomUUID(),
    })),
    remarks: entry.remarks,
  }));

  const [open, setOpen] = useState({
    project: false,
    span: false,
    items: false,
    measurements: true,
  });

  const set = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));

  const activeProject = useMemo(() => {
    if (entry.project) {
      return {
        _id: entry.project._id,
        name: entry.project.name,
        code: entry.project.code ?? "",
        status: entry.project.status ?? "",
        description: entry.project.description ?? "",
      };
    }
    const p = activeSpan?.project;
    if (!p) return null;
    return {
      _id: p._id,
      name: p.name,
      code: p.code ?? "",
      status: p.status ?? "",
      description: "",
    };
  }, [entry.project, activeSpan]);

  const distanceProgressed = useMemo(
    () => calcDistance(form.activityStartChain, form.activityEndChain),
    [form.activityStartChain, form.activityEndChain],
  );

  const lineItemCount = form.lineItems.filter((li) => li.label).length;

  const sectionComplete = {
    project: !!activeProject,
    span: !!activeSpan && !spanLoading,
    items: lineItemCount > 0,
    measurements: lineItemCount > 0,
  };

  const canSubmit = sectionComplete.items;

  const handleAddLine = () => addLine(form, set);
  const handleRemoveLine = (id) => removeLine(form, set, id);
  const handleUpdateLine = (id, patch) => updateLine(form, set, id, patch);

  const toggle = (key) => setOpen((prev) => ({ ...prev, [key]: !prev[key] }));

  const handleSubmit = async () => {
    if (!canSubmit) return;
    try {
      setSaving(true);
      await updateEmbEntry({
        variables: {
          _id: entry._id,
          lineItems: form.lineItems
            .filter((li) => li.label)
            .map((li) =>
              deepClean(li, [
                "__typename",
                "localId",
                "createdAt",
                "updatedAt",
                "cumulativeProgress",
              ]),
            ),
        },
        update(cache) {
          cache.evict({ fieldName: "embEntries" });
          cache.evict({ fieldName: "activities" });
          cache.gc();
        },
      });
      setSaving(false);
      onSaved();
    } catch (error) {
      console.error("Update error:", error);
      setSaving(false);
      alert("Update failed. Please try again.");
    }
  };

  const sections = [
    {
      key: "project",
      step: 1,
      title: "Project",
      summary: activeProject
        ? `${activeProject.name}${activeProject.code ? ` (${activeProject.code})` : ""}`
        : entry.project?.name ?? "Project",
      disabled: false,
      content: (
        <StepEditProjectReadOnly
          activeProject={activeProject}
          loading={false}
          error={null}
        />
      ),
    },
    {
      key: "span",
      step: 2,
      title: "Span & activity extent",
      summary: activeSpan
        ? `${activeSpan.name}${distanceProgressed != null ? ` · ${distanceProgressed} progressed` : ""}`
        : entry.span?.name ?? "Span",
      disabled: false,
      content: (
        <StepEditSpanReadOnly
          activeSpan={activeSpan}
          form={form}
          distanceProgressed={distanceProgressed}
          loading={spanLoading}
        />
      ),
    },
    {
      key: "items",
      step: 3,
      title: "Chapter & line items",
      summary:
        activeChapter && lineItemCount
          ? `${activeChapter.name} · ${lineItemCount} item${lineItemCount !== 1 ? "s" : ""}`
          : activeChapter?.name ?? form.chapter ?? "Line items",
      disabled: !sectionComplete.span,
      content: (
        <StepChapterItems
          form={form}
          activeSpan={activeSpan}
          activeChapter={activeChapter}
          onChapterChange={() => {}}
          onAddLine={handleAddLine}
          onRemoveLine={handleRemoveLine}
          onUpdateLine={handleUpdateLine}
          chapterLocked
        />
      ),
    },
    {
      key: "measurements",
      step: 4,
      title: "Measurements",
      summary:
        lineItemCount > 0
          ? `${lineItemCount} item${lineItemCount !== 1 ? "s" : ""} to measure`
          : "Enter measurements for each item",
      disabled: !sectionComplete.items,
      content: <StepMeasurements form={form} updateLine={handleUpdateLine} />,
    },
  ];

  const formPanel = (
    <div
      className="emb-entry entry-form-compact"
      style={{ display: "flex", flexDirection: "column", gap: 8 }}
    >
      {spanError && (
        <div className="emb-lock-banner emb-lock-banner--warn">
          Span details may be incomplete: {spanError.message}
        </div>
      )}

      {sections.map((s) => (
        <CollapsibleSection
          key={s.key}
          step={s.step}
          title={s.title}
          summary={s.summary}
          isOpen={open[s.key]}
          isComplete={sectionComplete[s.key]}
          isDisabled={s.disabled}
          onToggle={() => toggle(s.key)}
        >
          {s.content}
        </CollapsibleSection>
      ))}

      <div className="emb-form-actions" style={{ display: "flex", gap: 10 }}>
        <button
          type="button"
          className="btn btn-outline"
          style={{ flex: 1, minHeight: 48, fontSize: 14 }}
          onClick={onCancel}
        >
          Cancel
        </button>
        <button
          type="button"
          className="btn btn-primary"
          style={{ flex: 2, minHeight: 48, fontSize: 14, fontWeight: 700 }}
          onClick={handleSubmit}
          disabled={saving || !canSubmit}
        >
          {saving ? (
            <Spinner size={16} color="var(--on-accent)" />
          ) : (
            "✓ Save Changes"
          )}
        </button>
      </div>
    </div>
  );

  const summary = (
    <EntryLiveSummary
      form={form}
      activeProject={activeProject}
      activeSpan={activeSpan}
      activeChapter={activeChapter}
      distanceProgressed={distanceProgressed}
    />
  );

  const entryDate = new Date(entry.createdAt).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });

  return (
    <div
      className="fade-up emb-entry emb-entry-page"
      style={{ maxWidth: wide ? 1100 : 640, margin: "0 auto" }}
    >
      <PageHeader
        title="Edit e-MB Entry"
        subtitle={`Submitted ${entryDate} · ${entry.status ?? "SUBMITTED"}`}
      />

      {remarksText(form.remarks) && (
        <ReadOnlyRemarks remarks={form.remarks} />
      )}

      {wide ? (
        <div style={{ display: "flex", gap: 20, alignItems: "flex-start" }}>
          <div style={{ flex: 1, minWidth: 0 }}>{formPanel}</div>
          <div style={{ width: 260, flexShrink: 0 }}>{summary}</div>
        </div>
      ) : (
        <>
          {formPanel}
          <div style={{ marginTop: 16 }}>{summary}</div>
        </>
      )}
    </div>
  );
}

function ReadOnlyRemarks({ remarks }) {
  const text = remarksText(remarks);
  if (!text) return null;
  return (
    <div className="emb-data-panel" style={{ marginBottom: 12 }}>
      <div className="emb-data-panel__title">Entry remarks</div>
      <div style={{ fontSize: "var(--emb-font-sm)", color: "var(--emb-text-muted)" }}>
        {text}
      </div>
    </div>
  );
}
