import { useState } from "react";
import { Modal } from "../../../../components/common/index.jsx";
import CameraCapture from "./CameraCapture.jsx";

export default function PhotoCaptureModal({
  open,
  onClose,
  fieldLabel,
  photos,
  setPhotos,
}) {
  const [editingId, setEditingId] = useState(null);
  const editing = photos.find((p) => p.id === editingId);

  if (!open) return null;

  const updateCaption = (id, caption) =>
    setPhotos(photos.map((p) => (p.id === id ? { ...p, caption } : p)));

  const removePhoto = (id) => {
    setPhotos(photos.filter((p) => p.id !== id));
    if (editingId === id) setEditingId(null);
  };

  return (
    <Modal
      title={`Photos — ${fieldLabel}`}
      onClose={onClose}
      size="lg"
      footer={
        <button type="button" className="btn btn-primary" onClick={onClose}>
          Done
        </button>
      }
    >
      <CameraCapture photos={photos} setPhotos={setPhotos} fieldLabel={fieldLabel} compact />

      {photos.length > 0 && (
        <div style={{ marginTop: 20 }}>
          <div
            style={{
              fontSize: 11,
              fontWeight: 700,
              color: "var(--text2)",
              textTransform: "uppercase",
              letterSpacing: ".06em",
              marginBottom: 10,
            }}
          >
            Captured ({photos.length})
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {photos.map((p) => (
              <div
                key={p.id}
                style={{
                  display: "flex",
                  gap: 10,
                  alignItems: "center",
                  padding: "8px 10px",
                  borderRadius: 10,
                  border: "1px solid var(--border)",
                  background: editingId === p.id ? "rgba(244,160,28,.08)" : "rgba(255,255,255,.03)",
                  cursor: "pointer",
                }}
                onClick={() => setEditingId(p.id)}
              >
                <img
                  src={p.url}
                  alt=""
                  style={{
                    width: 48,
                    height: 48,
                    objectFit: "cover",
                    borderRadius: 8,
                    flexShrink: 0,
                  }}
                />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 12, fontWeight: 600 }}>
                    {p.caption || "No caption"}
                  </div>
                  {p.pointLocation?.coordinates && (
                    <div style={{ fontSize: 10, color: "var(--text3)", marginTop: 2 }}>
                      📍 {p.pointLocation.coordinates[1]?.toFixed(5)},{" "}
                      {p.pointLocation.coordinates[0]?.toFixed(5)}
                    </div>
                  )}
                </div>
                <button
                  type="button"
                  className="btn btn-danger btn-sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    removePhoto(p.id);
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {editing && (
        <div
          style={{
            marginTop: 16,
            padding: 14,
            borderRadius: 12,
            border: "1px solid rgba(244,160,28,.3)",
            background: "rgba(244,160,28,.06)",
          }}
        >
          <div style={{ fontSize: 12, fontWeight: 700, marginBottom: 8 }}>Edit caption</div>
          <input
            className="form-control"
            value={editing.caption}
            onChange={(e) => updateCaption(editing.id, e.target.value)}
            placeholder="Describe this photo…"
            autoFocus
          />
        </div>
      )}
    </Modal>
  );
}
