import { useState } from "react";
import { Spinner } from "../../../components/common/index.jsx";

/**
 * @param {{ id: string, label: string, sub?: string }[]} items
 * @param {string[]} selected
 * @param {(id: string) => void} onToggle
 */
export default function AssignmentMultiSelect({
  label,
  required,
  items,
  selected,
  onToggle,
  loading,
  emptyMessage = "No options",
  disabled,
}) {
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();
  const filtered = q
    ? items.filter(
        (i) =>
          i.label.toLowerCase().includes(q) ||
          (i.sub && i.sub.toLowerCase().includes(q)),
      )
    : items;

  const selectedItems = items.filter((i) =>
    selected.some((id) => String(id) === String(i.id)),
  );

  return (
    <div style={{ marginBottom: 16 }}>
      <div
        style={{
          fontSize: 11,
          fontWeight: 600,
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          color: "var(--text2)",
          marginBottom: 6,
        }}
      >
        {label}
        {required && (
          <span style={{ color: "var(--red)", marginLeft: 2 }}>*</span>
        )}
      </div>

      <div
        style={{
          border: "1px solid var(--border)",
          borderRadius: 8,
          overflow: "hidden",
          opacity: disabled ? 0.6 : 1,
          pointerEvents: disabled ? "none" : "auto",
        }}
      >
        {items.length > 4 && (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "7px 10px",
              borderBottom: "1px solid var(--border)",
              background: "rgba(255,255,255,.02)",
            }}
          >
            <input
              className="form-control"
              style={{
                border: "none",
                background: "transparent",
                padding: 0,
                fontSize: 12,
                flex: 1,
              }}
              placeholder="Search…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
            {query && (
              <button
                type="button"
                onClick={() => setQuery("")}
                style={{
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  color: "var(--text3)",
                  fontSize: 13,
                }}
              >
                ✕
              </button>
            )}
          </div>
        )}

        <div style={{ maxHeight: 200, overflowY: "auto" }}>
          {loading ? (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                padding: 14,
              }}
            >
              <Spinner size={16} />
              <span style={{ fontSize: 12, color: "var(--text2)" }}>
                Loading…
              </span>
            </div>
          ) : filtered.length === 0 ? (
            <div
              style={{
                padding: 14,
                fontSize: 12,
                color: "var(--text3)",
                textAlign: "center",
              }}
            >
              {query ? `No matches for "${query}"` : emptyMessage}
            </div>
          ) : (
            filtered.map((item) => {
              const active = selected.some(
                (id) => String(id) === String(item.id),
              );
              return (
                <div
                  key={item.id}
                  role="button"
                  tabIndex={0}
                  onClick={() => onToggle(item.id)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") onToggle(item.id);
                  }}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    padding: "8px 10px",
                    cursor: "pointer",
                    background: active
                      ? "rgba(244,160,28,.08)"
                      : "transparent",
                    borderBottom: "1px solid var(--border)",
                  }}
                >
                  <div
                    style={{
                      width: 16,
                      height: 16,
                      borderRadius: 3,
                      flexShrink: 0,
                      border: `2px solid ${active ? "var(--accent)" : "var(--border)"}`,
                      background: active ? "var(--accent)" : "transparent",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    {active && (
                      <span
                        style={{
                          fontSize: 10,
                          color: "var(--navy)",
                          fontWeight: 700,
                        }}
                      >
                        ✓
                      </span>
                    )}
                  </div>
                  <div style={{ minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: 12,
                        fontWeight: active ? 600 : 400,
                        color: active ? "var(--accent)" : "var(--text)",
                      }}
                    >
                      {item.label}
                    </div>
                    {item.sub && (
                      <div
                        style={{
                          fontSize: 10,
                          color: "var(--text3)",
                          marginTop: 1,
                        }}
                      >
                        {item.sub}
                      </div>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {selectedItems.length > 0 && (
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 4,
              padding: "6px 10px",
              borderTop: "1px solid var(--border)",
              background: "rgba(255,255,255,.02)",
            }}
          >
            {selectedItems.map((item) => (
              <span
                key={item.id}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 4,
                  padding: "2px 8px",
                  borderRadius: 20,
                  fontSize: 11,
                  fontWeight: 600,
                  background: "rgba(244,160,28,.12)",
                  border: "1px solid rgba(244,160,28,.3)",
                  color: "var(--accent)",
                }}
              >
                {item.label}
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onToggle(item.id);
                  }}
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "inherit",
                    padding: 0,
                    lineHeight: 1,
                  }}
                  aria-label={`Remove ${item.label}`}
                >
                  ×
                </button>
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export function toggleSelection(list, id) {
  const key = String(id);
  return list.some((x) => String(x) === key)
    ? list.filter((x) => String(x) !== key)
    : [...list, key];
}
