import { Spinner } from "../../../../components/common/index.jsx";
import ReadOnlyPanel from "./ReadOnlyPanel.jsx";

function EndpointCard({ label, variant, point }) {
  if (!point) return null;
  return (
    <div className={`emb-endpoint-card emb-endpoint-card--${variant}`}>
      <div className="emb-endpoint-card__label">{label}</div>
      <div className="emb-endpoint-card__place">{point.placeName || "—"}</div>
      <div className="emb-endpoint-card__chain">
        Chain {point.chainNumber ?? "—"}
      </div>
    </div>
  );
}

export default function StepEditSpanReadOnly({
  activeSpan,
  form,
  distanceProgressed,
  loading,
}) {
  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 0" }}>
        <Spinner size={16} />
        <span style={{ fontSize: "var(--emb-font-sm)", color: "var(--emb-text-muted)" }}>
          Loading span…
        </span>
      </div>
    );
  }

  if (!activeSpan) {
    return (
      <div className="emb-lock-banner emb-lock-banner--warn">
        Could not load span details for this entry.
      </div>
    );
  }

  return (
    <>
      <div className="emb-lock-banner">
        Locked — span and activity extent cannot be changed
      </div>

      <ReadOnlyPanel
        title="Span"
        rows={[
          ["Name", activeSpan.name],
          ["Status", activeSpan.status],
        ]}
      />

      <div className="emb-endpoint-grid">
        <EndpointCard label="Start point" variant="start" point={activeSpan.startPoint} />
        <EndpointCard label="End point" variant="end" point={activeSpan.endPoint} />
      </div>

      <ReadOnlyPanel
        title="Activity extent"
        rows={[
          [
            "Chain range",
            form.activityStartChain !== "" && form.activityEndChain !== ""
              ? `${form.activityStartChain} → ${form.activityEndChain}`
              : null,
          ],
          [
            "Progress",
            distanceProgressed != null ? `${distanceProgressed} chain` : null,
          ],
          ["Location notes", form.locationDescription],
        ]}
      />
    </>
  );
}
