import { useEffect } from "react";
import { resolvePhotoUrl } from "../../../utils/gisMap.js";

export default function GisPhotoLightbox({ photo, onClose }) {
  useEffect(() => {
    if (!photo) return;
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [photo, onClose]);

  if (!photo) return null;
  const url = resolvePhotoUrl(photo);

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Photo preview"
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 2000,
        background: "rgba(0, 0, 0, 0.88)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 24,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "var(--card)",
          borderRadius: 12,
          overflow: "hidden",
          maxWidth: "min(90vw, 720px)",
          width: "100%",
          border: "1px solid var(--border)",
          boxShadow: "var(--shadow)",
        }}
      >
        {url ? (
          <img
            src={url}
            alt={photo.caption || "Field photo"}
            style={{
              width: "100%",
              display: "block",
              maxHeight: "70vh",
              objectFit: "contain",
              background: "#000",
            }}
          />
        ) : (
          <div style={{ padding: 32, textAlign: "center", color: "var(--text2)" }}>
            Photo URL not available
          </div>
        )}

        <div
          style={{
            padding: "12px 16px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: 12,
          }}
        >
          <div style={{ fontSize: 13, color: "var(--text2)" }}>
            {photo.caption || "Field measurement photo"}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            {url && (
              <a
                href={url}
                target="_blank"
                rel="noreferrer"
                className="btn btn-outline btn-sm"
                onClick={(e) => e.stopPropagation()}
              >
                Open in new tab
              </a>
            )}
            <button type="button" className="btn btn-primary btn-sm" onClick={onClose}>
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
