import { useState, useMemo, useEffect } from "react";
import { Q, M, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery, useApiMutation } from "../../../apollo/useApi.js";
import {
  Modal,
  FormField,
  Spinner,
  AlertBanner,
} from "../../../components/common/index.jsx";
import { mergeProjectOptions } from "./userSpanAssignment.js";
import AssignmentMultiSelect, {
  toggleSelection,
} from "./AssignmentMultiSelect.jsx";
import { usePortalRole } from "../../../hooks/usePortalRole.js";

export default function EngineerUserModal({
  editUser,
  currentUser,
  onClose,
  onSaved,
}) {
  const isEdit = !!editUser;
  const { lockUserRoleToFieldEngineer } = usePortalRole();
  const scopeProjects = useMemo(
    () => currentUser?.projects ?? [],
    [currentUser?.projects],
  );

  const [projectIds, setProjectIds] = useState(() =>
    (editUser?.projects ?? []).map((p) => p._id).filter(Boolean),
  );
  const [spanIds, setSpanIds] = useState(() =>
    (editUser?.spans ?? []).map((s) => s._id).filter(Boolean),
  );
  const [name, setName] = useState(editUser?.name ?? "");
  const [designation, setDesignation] = useState(editUser?.designation ?? "");
  const [email, setEmail] = useState(editUser?.email ?? "");
  const [role, setRole] = useState(() =>
    lockUserRoleToFieldEngineer
      ? "field_engineer"
      : editUser?.role ?? "field_engineer",
  );
  const [password, setPassword] = useState("");
  const [formError, setFormError] = useState("");

  const {
    data: projectsData,
    loading: projectsLoading,
    error: projectsError,
  } = useApiQuery(Q.projects.list, {
    fields: PRESETS.projectEntryForm,
    fetchPolicy: "cache-and-network",
    queryOptions: {
      fragments: [],
      pagination: "page limit totalPages totalDocuments",
    },
    variables: { page: 1, limit: 200 },
  });

  const { data: spansData, loading: spansLoading } = useApiQuery(Q.spans.list, {
    fields: PRESETS.spanStaffPicker,
    fetchPolicy: "cache-and-network",
    variables: {
      page: 1,
      limit: 300,
      projects: projectIds.length ? projectIds : undefined,
    },
    skip: projectIds.length === 0,
  });

  const projectOptions = useMemo(
    () =>
      mergeProjectOptions(
        projectsData?.projects?.data,
        scopeProjects,
      ),
    [projectsData, scopeProjects],
  );

  const projectSelectItems = useMemo(
    () =>
      projectOptions.map((p) => ({
        id: p._id,
        label: p.name,
        sub: p.code || undefined,
      })),
    [projectOptions],
  );

  const spanOptions = useMemo(
    () => spansData?.spans?.data ?? [],
    [spansData],
  );

  const spanSelectItems = useMemo(
    () =>
      spanOptions.map((s) => ({
        id: s._id,
        label: s.name,
        sub: [s.status, s.project?.name].filter(Boolean).join(" · ") || undefined,
      })),
    [spanOptions],
  );

  useEffect(() => {
    if (!projectIds.length) {
      setSpanIds([]);
      return;
    }
    const valid = new Set(spanOptions.map((s) => String(s._id)));
    setSpanIds((prev) => prev.filter((id) => valid.has(String(id))));
  }, [projectIds, spanOptions]);

  const [createUser, { loading: creating }] = useApiMutation(M.users.create, {
    fields: "_id name email role projects { _id name } spans { _id name }",
  });
  const [updateUserRecord, { loading: updating }] = useApiMutation(
    M.users.update,
    { fields: "_id" },
  );

  const saving = creating || updating;

  const handleSubmit = async () => {
    setFormError("");
    const n = name.trim();
    const d = designation.trim();
    const em = email.trim();

    if (!projectIds.length) {
      setFormError("Select at least one project.");
      return;
    }
    if (!spanIds.length) {
      setFormError("Select at least one span.");
      return;
    }
    if (!n) {
      setFormError("Name is required.");
      return;
    }
    if (!em) {
      setFormError("Email is required.");
      return;
    }

    const effectiveRole = lockUserRoleToFieldEngineer ? "field_engineer" : role;

    const userInput = {
      name: n,
      designation: d || undefined,
      email: em,
      role: effectiveRole,
      projects: projectIds,
      spans: spanIds,
    };

    if (!isEdit) {
      if (!password) {
        setFormError("Password is required.");
        return;
      }
      try {
        const { errors } = await createUser({
          variables: {
            userInput: { ...userInput, password },
          },
        });
        if (errors?.length)
          throw new Error(errors.map((e) => e.message).join(", "));
        onSaved();
        onClose();
      } catch (e) {
        setFormError(e.message || "Create failed");
      }
      return;
    }

    if (password.trim()) userInput.password = password.trim();

    try {
      const { errors } = await updateUserRecord({
        variables: { id: editUser._id, userInput },
      });
      if (errors?.length)
        throw new Error(errors.map((e) => e.message).join(", "));
      onSaved();
      onClose();
    } catch (e) {
      setFormError(e.message || "Update failed");
    }
  };

  return (
    <Modal
      title={isEdit ? `Edit user — ${editUser.name}` : "Add user"}
      onClose={onClose}
      size="md"
      footer={
        <>
          <button
            type="button"
            className="btn btn-outline"
            onClick={onClose}
            disabled={saving}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => void handleSubmit()}
            disabled={saving}
          >
            {saving ? (
              <Spinner size={14} color="var(--on-accent)" />
            ) : isEdit ? (
              "Save"
            ) : (
              "Create user"
            )}
          </button>
        </>
      }
    >
      {formError && <AlertBanner type="error" message={formError} />}
      {projectsError && (
        <AlertBanner
          type="error"
          message={`Could not load projects: ${projectsError.message}`}
        />
      )}
      {!projectsLoading && !projectsError && projectSelectItems.length === 0 && (
        <AlertBanner
          type="warning"
          message="No projects are assigned to your account. Ask a system admin to add you to a project, then sign out and sign in again."
        />
      )}

      <p style={{ fontSize: 12, color: "var(--text3)", marginBottom: 14 }}>
        Assign one or more projects and spans. Span IDs are stored on the user and
        the user is added to each span&apos;s staff automatically.
      </p>

      <AssignmentMultiSelect
        label="Projects"
        required
        items={projectSelectItems}
        selected={projectIds}
        onToggle={(id) => setProjectIds((prev) => toggleSelection(prev, id))}
        loading={projectsLoading}
        emptyMessage="No projects in your scope"
      />

      <AssignmentMultiSelect
        label="Spans"
        required
        items={spanSelectItems}
        selected={spanIds}
        onToggle={(id) => setSpanIds((prev) => toggleSelection(prev, id))}
        loading={spansLoading && projectIds.length > 0}
        disabled={projectIds.length === 0}
        emptyMessage={
          projectIds.length
            ? "No spans for selected projects"
            : "Select at least one project first"
        }
      />

      <div className="form-row">
        <FormField label="Full name" required>
          <input
            className="form-control"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Rajesh Kumar"
          />
        </FormField>
        <FormField label="Designation">
          <input
            className="form-control"
            value={designation}
            onChange={(e) => setDesignation(e.target.value)}
            placeholder="e.g. Field Engineer"
          />
        </FormField>
      </div>

      <FormField label="Email" required>
        <input
          className="form-control"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          disabled={isEdit}
          placeholder="name@example.com"
        />
      </FormField>

      <div className="form-row">
        <FormField label="Role" required>
          {lockUserRoleToFieldEngineer ? (
            <input
              className="form-control"
              value="Field engineer"
              readOnly
              disabled
            />
          ) : (
            <select
              className="form-control"
              value={role}
              onChange={(e) => setRole(e.target.value)}
            >
              <option value="field_engineer">Field engineer</option>
              <option value="project_admin">Project admin</option>
            </select>
          )}
        </FormField>
        <FormField
          label={isEdit ? "Password (optional)" : "Password"}
          required={!isEdit}
        >
          <input
            className="form-control"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder={
              isEdit ? "Leave blank to keep current" : "Minimum 8 characters"
            }
            autoComplete="new-password"
          />
        </FormField>
      </div>
    </Modal>
  );
}
