/** Normalize project ref from API or session user (`_id` vs `id`, string id). */
export function normalizeProjectOption(p) {
  if (p == null) return null;
  if (typeof p === "string") return { _id: p, name: p };
  const _id = p._id ?? p.id;
  if (!_id) return null;
  return {
    _id: String(_id),
    name: p.name || p.code || "Project",
    code: p.code,
    status: p.status,
  };
}

/** API list is already scoped to the user; merge session projects as fallback. */
export function mergeProjectOptions(apiProjects, scopeProjects) {
  const byId = new Map();
  for (const p of apiProjects ?? []) {
    const n = normalizeProjectOption(p);
    if (n) byId.set(n._id, n);
  }
  for (const p of scopeProjects ?? []) {
    const n = normalizeProjectOption(p);
    if (n && !byId.has(n._id)) byId.set(n._id, n);
  }
  return Array.from(byId.values()).sort((a, b) =>
    a.name.localeCompare(b.name),
  );
}