/**
 * Client-side progress aggregation for span TargetedValues vs activities.
 * Backend can later replace this with a dedicated spanProgressReport resolver.
 */
import { getChapterName, getChapterId } from "./helpers.js";

/** Set true only when debugging progress matching in the console. */
const DEBUG_PROGRESS = false;

/** Normalize measurement labels for matching (Qty/qty, Lenght/Length, etc.). */
const MEASUREMENT_LABEL_ALIASES = {
  lenght: "length",
  length: "length",
  qty: "qty",
  quantity: "qty",
};

export function normalizeMeasurementLabel(label) {
  if (label == null) return "";
  const key = String(label).trim().toLowerCase();
  return MEASUREMENT_LABEL_ALIASES[key] ?? key;
}

export function measurementLabelsMatch(activityLabel, targetLabel) {
  return (
    normalizeMeasurementLabel(activityLabel) ===
    normalizeMeasurementLabel(targetLabel)
  );
}

export function activityMatchesTargetChapter(
  activity,
  target,
  resolvedChapterName,
) {
  const activityChapterId = getChapterId(activity?.chapter);
  if (
    activityChapterId &&
    target.chapterId &&
    String(activityChapterId) === String(target.chapterId)
  ) {
    return true;
  }
  const activityName = getChapterName(activity?.chapter);
  if (!activityName || !resolvedChapterName) return false;
  return (
    activityName === resolvedChapterName ||
    activityName.trim().toLowerCase() ===
      resolvedChapterName.trim().toLowerCase()
  );
}

function lineItemMatchesTarget(li, target, { itemLabel } = {}) {
  if (String(li._id) === String(target.itemId)) return true;
  if (li.code && String(li.code) === String(target.itemId)) return true;
  if (li.itemId && String(li.itemId) === String(target.itemId)) return true;
  if (
    itemLabel &&
    li.label &&
    itemLabel.trim().toLowerCase() === li.label.trim().toLowerCase()
  ) {
    return true;
  }
  return false;
}

function debugProgress(scope, data) {
  if (!DEBUG_PROGRESS) return;
  console.groupCollapsed(`[progressReport] ${scope}`);
  console.log(data);
  console.groupEnd();
}

/** @returns {number} */
export function measurementToNumber(m) {
  if (!m) return 0;
  if (m.fixedNumber != null && m.fixedNumber !== "") {
    return Number(m.fixedNumber) || 0;
  }
  const v = m.value;
  if (v == null || v === "") return 0;
  if (m.type === "boolean") return v === true || v === "true" ? 1 : 0;
  if (Array.isArray(v)) {
    if (v.length && typeof v[0] === "object") return v.length;
    return v.reduce((s, x) => s + (Number(x) || 0), 0);
  }
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

/** Sum matching measurement values from one activity lineItems. */
export function sumActivityTarget(activity, target, matchContext = {}) {
  return extractActivityContribution(activity, target, matchContext).delta;
}

/** Matched measurements from one activity for a target. */
export function extractActivityContribution(
  activity,
  target,
  { resolvedChapterName, itemLabel, debugKey } = {},
) {
  const result = { delta: 0, matches: [] };
  const activityChapter = getChapterName(activity?.chapter);
  const activityChapterId = getChapterId(activity?.chapter);
  const skipReasons = [];

  if (!activity) {
    if (debugKey)
      debugProgress(`contribution:${debugKey}`, { skip: "no activity" });
    return result;
  }

  if (!activityMatchesTargetChapter(activity, target, resolvedChapterName)) {
    if (debugKey) {
      debugProgress(`contribution:${debugKey}`, {
        activityId: activity._id,
        skip: "chapter mismatch (id and name)",
        activityChapter,
        activityChapterId,
        targetChapterId: target.chapterId,
        resolvedChapterName,
        activityChapterRaw: activity.chapter,
      });
    }
    return result;
  }

  const lineItems = activity.lineItems ?? [];
  if (!lineItems.length) {
    if (debugKey)
      debugProgress(`contribution:${debugKey}`, {
        activityId: activity._id,
        skip: "no lineItems",
      });
    return result;
  }

  for (const li of lineItems) {
    if (!lineItemMatchesTarget(li, target, { itemLabel })) {
      skipReasons.push({
        lineItemId: li._id,
        lineItemLabel: li.label,
        reason: "item mismatch",
        targetItemId: target.itemId,
        resolvedItemLabel: itemLabel,
      });
      continue;
    }

    const measurements = li.measurements ?? [];
    if (!measurements.length) {
      skipReasons.push({ lineItemId: li._id, reason: "no measurements on line item" });
      continue;
    }

    for (const m of measurements) {
      if (!measurementLabelsMatch(m.label, target.measurementLabel)) {
        skipReasons.push({
          lineItemId: li._id,
          measurementLabel: m.label,
          targetMeasurementLabel: target.measurementLabel,
          normalizedActivity: normalizeMeasurementLabel(m.label),
          normalizedTarget: normalizeMeasurementLabel(target.measurementLabel),
          reason: "measurement label mismatch",
          measurementValue: m.value,
          measurementType: m.type,
        });
        continue;
      }

      const value = measurementToNumber(m);
      if (value <= 0) {
        skipReasons.push({
          lineItemId: li._id,
          measurementLabel: m.label,
          reason: "measurement value <= 0",
          rawValue: m.value,
          fixedNumber: m.fixedNumber,
          parsedValue: value,
        });
        continue;
      }

      result.delta += value;
      result.matches.push({
        lineItemId: li._id,
        lineItemLabel: li.label ?? li.itemCode ?? "—",
        measurement: m,
        value,
      });
    }
  }

  if (debugKey) {
    debugProgress(`contribution:${debugKey}`, {
      activityId: activity._id,
      status: activity.status,
      activityChapter,
      activityChapterId,
      resolvedChapterName,
      target: {
        chapterId: target.chapterId,
        itemId: target.itemId,
        measurementLabel: target.measurementLabel,
        resolvedChapterName,
        itemLabel,
      },
      lineItemsSummary: lineItems.map((li) => ({
        _id: li._id,
        label: li.label,
        code: li.code,
        measurementLabels: (li.measurements ?? []).map((m) => ({
          label: m.label,
          value: m.value,
          fixedNumber: m.fixedNumber,
        })),
      })),
      skipReasons,
      delta: result.delta,
      matches: result.matches.length,
    });
  }

  return result;
}

export function formatMeasurementDisplay(m) {
  if (!m) return "—";
  if (m.fixedNumber != null && m.fixedNumber !== "") {
    return `${m.fixedNumber}${m.unit ? ` ${m.unit}` : ""}`;
  }
  const v = m.value;
  if (m.type === "boolean") return v === true || v === "true" ? "Yes" : "No";
  if (Array.isArray(v)) {
    if (v.length && typeof v[0] === "object") return `${v.length} rows`;
    return v.join(", ");
  }
  if (v == null || v === "") return "—";
  return `${v}${m.unit ? ` ${m.unit}` : ""}`;
}

export function formatProgressAmount(achieved, targetValue, unit = "") {
  const u = unit ? ` ${unit}` : "";
  const achievedStr = achieved.toLocaleString("en-IN");
  const targetStr = targetValue.toLocaleString("en-IN");
  const pct =
    targetValue > 0
      ? Math.min(100, Math.round((achieved / targetValue) * 100))
      : achieved > 0
        ? 100
        : 0;
  return {
    achieved,
    targetValue,
    pct,
    summary: `${achievedStr}${u} / ${targetStr}${u}`,
    percentLabel: `${pct}% done`,
  };
}

function filterActivitiesForReport(span, activities, range, { statusFilter } = {}) {
  const inRange = (createdAt) => {
    if (!range?.start && !range?.end) return true;
    const t = new Date(createdAt).getTime();
    if (range.start && t < range.start.getTime()) return false;
    if (range.end && t > range.end.getTime()) return false;
    return true;
  };

  const list = activities ?? [];
  const rejected = [];
  const kept = [];

  for (const a of list) {
    if (String(a.span?._id) !== String(span._id)) {
      rejected.push({
        activityId: a._id,
        reason: "span mismatch",
        activitySpanId: a.span?._id,
        expectedSpanId: span._id,
        activitySpan: a.span,
      });
      continue;
    }
    if (statusFilter && a.status !== statusFilter) {
      rejected.push({
        activityId: a._id,
        reason: "status filter",
        status: a.status,
        statusFilter,
      });
      continue;
    }
    if (!inRange(a.createdAt)) {
      rejected.push({
        activityId: a._id,
        reason: "out of date range",
        createdAt: a.createdAt,
        range,
      });
      continue;
    }
    kept.push(a);
  }

  debugProgress("filterActivities", {
    spanId: span._id,
    spanName: span.name,
    inputCount: list.length,
    keptCount: kept.length,
    rejectedCount: rejected.length,
    range,
    statusFilter: statusFilter ?? "(none)",
    rejectedSample: rejected.slice(0, 10),
    keptSample: kept.slice(0, 3).map((a) => ({
      _id: a._id,
      status: a.status,
      createdAt: a.createdAt,
      chapter: getChapterName(a.chapter),
      spanId: a.span?._id,
      lineItemCount: a.lineItems?.length ?? 0,
    })),
  });

  return kept;
}

/** Detailed progress rows: targets + contributing activities with measurements/photos. */
export function buildSpanProgressReport(
  span,
  activities,
  { fromDate, toDate, statusFilter } = {},
) {
  const targets = span?.TargetedValues ?? [];

  debugProgress("buildSpanProgressReport:start", {
    spanId: span?._id,
    spanName: span?.name,
    targetCount: targets.length,
    activityInputCount: activities?.length ?? 0,
    fromDate,
    toDate,
    statusFilter,
    spanChapterIds: (span?.chapters ?? []).map((c) => ({
      _id: c._id,
      name: c.name,
      itemCount: c.items?.length ?? 0,
      itemIds: (c.items ?? []).map((it) =>
        typeof it === "string" ? it : it._id,
      ),
      itemLabels: (c.items ?? []).map((it) =>
        typeof it === "string" ? null : it.label,
      ),
    })),
    projectChapterIds: (span?.project?.chapters ?? []).map((c) => ({
      _id: c._id,
      name: c.name,
      itemCount: c.items?.length ?? 0,
    })),
    targets,
  });

  if (!targets.length) {
    debugProgress("buildSpanProgressReport", { skip: "no TargetedValues on span" });
    return [];
  }

  const range = {
    start: fromDate ? new Date(`${fromDate}T00:00:00`) : null,
    end: toDate ? new Date(`${toDate}T23:59:59.999`) : null,
  };

  const filteredActivities = filterActivitiesForReport(span, activities, range, {
    statusFilter,
  });

  return targets.map((target, targetIndex) => {
    const targetKey = `${target.chapterId}__${target.itemId}__${target.measurementLabel}`;

    const meta = resolveTargetMeta(span, target, {
      activities: filteredActivities,
      projectChapters: span.project?.chapters,
      debugKey: `target-${targetIndex}`,
    });
    const chapterName = meta.chapterName;
    const targetValue = Number(target.targetValue) || 0;
    let achieved = 0;
    const contributors = [];

    debugProgress(`target:${targetKey}:start`, {
      target,
      resolvedMeta: meta,
      chapterNameForMatching: chapterName,
      filteredActivityCount: filteredActivities.length,
    });

    for (const [actIndex, activity] of filteredActivities.entries()) {
      const { delta, matches } = extractActivityContribution(activity, target, {
        resolvedChapterName: chapterName,
        itemLabel: meta.itemLabel,
        debugKey:
          actIndex < 3 ? `${targetKey}::activity[${actIndex}]` : undefined,
      });
      if (delta <= 0) continue;
      achieved += delta;
      contributors.push({
        activityId: activity._id,
        status: activity.status,
        chapterName: getChapterName(activity.chapter),
        locationDescription: activity.locationDescription,
        createdAt: activity.createdAt,
        updatedAt: activity.updatedAt,
        createdBy: activity.createdBy,
        delta,
        matches,
        lineItems: activity.lineItems ?? [],
      });
    }

    contributors.sort(
      (a, b) => new Date(b.createdAt) - new Date(a.createdAt),
    );

    const progress = formatProgressAmount(achieved, targetValue, meta.unit);

    debugProgress(`target:${targetKey}:result`, {
      itemLabel: meta.itemLabel,
      achieved,
      targetValue,
      pct: progress.pct,
      contributorCount: contributors.length,
      contributorIds: contributors.map((c) => c.activityId),
    });

    return {
      key: targetKey,
      ...target,
      ...meta,
      achieved,
      targetValue,
      pct: progress.pct,
      progress,
      entryCount: contributors.length,
      contributors,
    };
  });
}

function normalizeMeasurements(measurements) {
  if (!measurements) return [];
  if (typeof measurements === "string") {
    try {
      const parsed = JSON.parse(measurements);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return Array.isArray(measurements) ? measurements : [];
}

function itemMatchesId(entry, itemId) {
  if (entry == null) return false;
  if (typeof entry === "string") return String(entry) === String(itemId);
  return (
    String(entry._id) === String(itemId) ||
    (entry.code && String(entry.code) === String(itemId))
  );
}

function itemDisplayLabel(item) {
  if (!item || typeof item === "string") return null;
  return (
    item.label?.trim() ||
    item.code?.trim() ||
    item.description?.trim() ||
    null
  );
}

/** Resolve chapter + item from span (and optional project) chapter trees. */
export function findItemInChapters(chapters, chapterId, itemId, debugKey) {
  const list = chapters ?? [];
  let chapter = list.find((c) => String(c._id) === String(chapterId));
  let item = (chapter?.items ?? []).find((it) => itemMatchesId(it, itemId));
  let foundVia = item ? "chapterId+itemId" : null;

  if (!item) {
    for (const ch of list) {
      const found = (ch.items ?? []).find((it) => itemMatchesId(it, itemId));
      if (found) {
        chapter = ch;
        item = typeof found === "string" ? null : found;
        foundVia = "scan all chapters";
        break;
      }
    }
  }

  if (debugKey) {
    debugProgress(`findItem:${debugKey}`, {
      source: chapters === undefined ? "undefined" : `chapters[${list.length}]`,
      chapterId,
      itemId,
      foundVia: foundVia ?? "not found",
      chapterName: chapter?.name,
      itemLabel: itemDisplayLabel(item),
      itemRaw: item,
      availableChapterIds: list.map((c) => c._id),
      itemsInMatchedChapter: (chapter?.items ?? []).map((it) =>
        typeof it === "string"
          ? { ref: it }
          : { _id: it._id, label: it.label, code: it.code },
      ),
    });
  }

  return { chapter, item: typeof item === "string" ? null : item };
}

function resolveItemLabelFromActivities(activities, itemId) {
  for (const activity of activities ?? []) {
    for (const li of activity.lineItems ?? []) {
      if (String(li._id) !== String(itemId)) continue;
      return li.label?.trim() || li.code?.trim() || null;
    }
  }
  return null;
}

export function resolveTargetMeta(
  span,
  target,
  { activities, projectChapters, debugKey } = {},
) {
  const itemId = target.itemId;
  let { chapter, item } = findItemInChapters(
    span?.chapters,
    target.chapterId,
    itemId,
    debugKey ? `${debugKey}:span` : undefined,
  );

  let itemSource = item ? "span.chapters" : null;

  if (!item && projectChapters?.length) {
    const fromProject = findItemInChapters(
      projectChapters,
      target.chapterId,
      itemId,
      debugKey ? `${debugKey}:project` : undefined,
    );
    chapter = fromProject.chapter ?? chapter;
    item = fromProject.item ?? item;
    if (item) itemSource = "project.chapters";
  }

  const fromActivities = resolveItemLabelFromActivities(activities, itemId);
  let itemLabel = itemDisplayLabel(item) ?? fromActivities;

  if (!itemLabel) itemLabel = String(itemId);

  const measurements = normalizeMeasurements(item?.measurements);
  const measurement = measurements.find((m) =>
    measurementLabelsMatch(m.label, target.measurementLabel),
  );

  if (debugKey) {
    debugProgress(`resolveTargetMeta:${debugKey}`, {
      target,
      itemSource: itemSource ?? (fromActivities ? "activities.lineItems" : "fallback itemId"),
      itemLabel,
      chapterName: chapter?.name,
      chapterId: chapter?._id,
      targetChapterId: target.chapterId,
      chapterIdMatch: String(chapter?._id) === String(target.chapterId),
      itemFound: !!item,
      itemFromActivities: fromActivities,
      measurementLabelsOnItem: measurements.map((m) => m.label),
      targetMeasurementLabel: target.measurementLabel,
      unit: measurement?.unit ?? "",
      measurementMatch: !!measurement,
      normalizedTargetLabel: normalizeMeasurementLabel(target.measurementLabel),
    });
  }

  return {
    chapterName: chapter?.name ?? "—",
    chapterColor: chapter?.color ?? "var(--text3)",
    itemLabel,
    unit: measurement?.unit ?? "",
  };
}

export function buildTargetRows(span, activities, range, { statusFilter } = {}) {
  const targets = span.TargetedValues ?? [];
  if (!targets.length) return [];

  const inRange = (createdAt) => {
    if (!range?.start && !range?.end) return true;
    const t = new Date(createdAt).getTime();
    if (range.start && t < range.start.getTime()) return false;
    if (range.end && t > range.end.getTime()) return false;
    return true;
  };

  const filteredActivities = (activities ?? []).filter((a) => {
    if (String(a.span?._id) !== String(span._id)) return false;
    if (statusFilter && a.status !== statusFilter) return false;
    return inRange(a.createdAt);
  });

  return targets.map((target) => {
    const meta = resolveTargetMeta(span, target, {
      activities: filteredActivities,
      projectChapters: span.project?.chapters,
    });
    const chapterName = meta.chapterName;
    let achieved = 0;
    let entryCount = 0;

    for (const activity of filteredActivities) {
      const delta = sumActivityTarget(activity, target, {
        resolvedChapterName: chapterName,
        itemLabel: meta.itemLabel,
      });
      if (delta > 0) {
        achieved += delta;
        entryCount += 1;
      }
    }

    const targetValue = Number(target.targetValue) || 0;
    const pct =
      targetValue > 0
        ? Math.min(100, Math.round((achieved / targetValue) * 100))
        : achieved > 0
          ? 100
          : 0;

    return {
      key: `${target.chapterId}__${target.itemId}__${target.measurementLabel}`,
      ...target,
      ...meta,
      achieved,
      targetValue,
      pct,
      entryCount,
    };
  });
}

export function getPeriodRange(period, refDate = new Date()) {
  const d = new Date(refDate);
  d.setHours(0, 0, 0, 0);

  switch (period) {
    case "day": {
      const end = new Date(d);
      end.setHours(23, 59, 59, 999);
      return { start: d, end, label: d.toLocaleDateString("en-IN") };
    }
    case "week": {
      const day = d.getDay();
      const mondayOffset = day === 0 ? -6 : 1 - day;
      const start = new Date(d);
      start.setDate(d.getDate() + mondayOffset);
      start.setHours(0, 0, 0, 0);
      const end = new Date(start);
      end.setDate(start.getDate() + 6);
      end.setHours(23, 59, 59, 999);
      return {
        start,
        end,
        label: `${start.toLocaleDateString("en-IN")} – ${end.toLocaleDateString("en-IN")}`,
      };
    }
    case "month": {
      const start = new Date(d.getFullYear(), d.getMonth(), 1);
      const end = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999);
      return {
        start,
        end,
        label: start.toLocaleDateString("en-IN", { month: "long", year: "numeric" }),
      };
    }
    case "total":
    default:
      return { start: null, end: null, label: "All time (since span start)" };
  }
}

/**
 * Builds table rows for all 4 periods simultaneously (today / this week / this month / total).
 * Each row has { day, week, month, total } = { achieved, count, pct }.
 */
export function buildActivityTableRows(span, activities, { statusFilter } = {}) {
  const targets = span.TargetedValues ?? [];
  if (!targets.length) return [];

  const now = new Date();
  const ranges = {
    day: getPeriodRange("day", now),
    week: getPeriodRange("week", now),
    month: getPeriodRange("month", now),
    total: { start: null, end: null },
  };

  const inRange = (createdAt, range) => {
    if (!range.start && !range.end) return true;
    const t = new Date(createdAt).getTime();
    if (range.start && t < range.start.getTime()) return false;
    if (range.end && t > range.end.getTime()) return false;
    return true;
  };

  const spanActivities = (activities ?? []).filter((a) => {
    if (String(a.span?._id) !== String(span._id)) return false;
    if (statusFilter && a.status !== statusFilter) return false;
    return true;
  });

  return targets.map((target) => {
    const meta = resolveTargetMeta(span, target, {
      activities: spanActivities,
      projectChapters: span.project?.chapters,
    });
    const chapterName = meta.chapterName;

    const cols = {
      day: { achieved: 0, count: 0 },
      week: { achieved: 0, count: 0 },
      month: { achieved: 0, count: 0 },
      total: { achieved: 0, count: 0 },
    };

    for (const activity of spanActivities) {
      const delta = sumActivityTarget(activity, target, {
        resolvedChapterName: chapterName,
        itemLabel: meta.itemLabel,
      });
      if (delta <= 0) continue;
      for (const [period, range] of Object.entries(ranges)) {
        if (inRange(activity.createdAt, range)) {
          cols[period].achieved += delta;
          cols[period].count += 1;
        }
      }
    }

    const targetValue = Number(target.targetValue) || 0;
    const calcPct = (achieved) =>
      targetValue > 0
        ? Math.min(100, Math.round((achieved / targetValue) * 100))
        : achieved > 0
          ? 100
          : 0;

    return {
      key: `${target.chapterId}__${target.itemId}__${target.measurementLabel}`,
      ...target,
      ...meta,
      targetValue,
      day: { ...cols.day, pct: calcPct(cols.day.achieved) },
      week: { ...cols.week, pct: calcPct(cols.week.achieved) },
      month: { ...cols.month, pct: calcPct(cols.month.achieved) },
      total: { ...cols.total, pct: calcPct(cols.total.achieved) },
    };
  });
}

export const PERIOD_OPTIONS = [
  { id: "day", label: "Today", icon: "📅" },
  { id: "week", label: "This Week", icon: "📆" },
  { id: "month", label: "This Month", icon: "🗓️" },
  { id: "total", label: "Total", icon: "∞" },
];

export function parseReportSearchParams(searchParams) {
  const spans = searchParams.get("spans")?.split(",").filter(Boolean) ?? [];
  const projects =
    searchParams.get("projects")?.split(",").filter(Boolean) ?? [];
  const createdBy =
    searchParams.get("createdBy")?.split(",").filter(Boolean) ?? [];
  return {
    status: searchParams.get("status") || undefined,
    spans,
    projects,
    createdBy,
    fromDate: searchParams.get("fromDate") || undefined,
    toDate: searchParams.get("toDate") || undefined,
  };
}

/** Activities query window: custom from/to overrides period when both set. */
export function activitiesQueryDates(period, refDate, urlFrom, urlTo) {
  if (urlFrom && urlTo) {
    return {
      fromDate: urlFrom,
      toDate: urlTo,
      label: `${urlFrom} – ${urlTo}`,
    };
  }
  const range = getPeriodRange(period, refDate);
  if (!range.start) return { fromDate: undefined, toDate: undefined, label: range.label };
  return {
    fromDate: range.start.toISOString(),
    toDate: range.end.toISOString(),
    label: range.label,
  };
}
