import { useAuth } from "./useAuth.js";

/**
 * Portal capabilities by logged-in role.
 * Vendor mirrors project admin with read-only projects/spans
 * and field-engineer-only user creation.
 */
export function usePortalRole() {
  const { user } = useAuth();
  const role = user?.role ?? "";
  const isVendor = role === "vendor";

  return {
    role,
    isVendor,
    isProjectAdmin: role === "project_admin",
    isFieldEngineer: role === "field_engineer",
    readOnlyProjects: isVendor,
    readOnlySpans: isVendor,
    lockUserRoleToFieldEngineer: isVendor,
  };
}
