import { useRef, useState } from "react";
import { AlertBanner } from "../../../../components/common/index.jsx";
import {
  downloadProjectTemplate,
  parseExcelFile,
} from "../projectExcelImport.js";

export default function ProjectExcelImportBar({
  chapters,
  setProj,
  setActCh,
  setActItem,
}) {
  const fileRef = useRef(null);
  const [importing, setImporting] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState("info");

  const applyChapters = (imported, mode) => {
    setProj((p) => {
      const nextChapters =
        mode === "replace" ? imported : [...p.chapters, ...imported];
      return { ...p, chapters: nextChapters };
    });
    if (imported.length > 0) {
      setActCh(imported[0]._id);
      const firstItem = imported[0].items?.[0];
      setActItem(firstItem?._id ?? null);
    }
  };

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;

    setImporting(true);
    setMessage(null);

    try {
      const buffer = await file.arrayBuffer();
      const { chapters: imported, errors, rowCount } = parseExcelFile(buffer);

      if (!imported.length) {
        setMessageType("error");
        setMessage(errors.join(" ") || "No chapters could be imported.");
        return;
      }

      let mode = "replace";
      if (chapters.length > 0) {
        const append = window.confirm(
          `Import ${imported.length} chapter(s) from ${rowCount} row(s)?\n\n` +
            "OK = Add to existing chapters\n" +
            "Cancel = Replace all existing chapters",
        );
        mode = append ? "append" : "replace";
        if (
          mode === "replace" &&
          !window.confirm(
            "This will remove all chapters currently in the builder. Continue?",
          )
        ) {
          return;
        }
      }

      applyChapters(imported, mode);

      const itemCount = imported.reduce((n, ch) => n + ch.items.length, 0);
      const fieldCount = imported.reduce(
        (n, ch) =>
          n + ch.items.reduce((m, it) => m + it.measurements.length, 0),
        0,
      );

      const warn =
        errors.length > 0
          ? ` (${errors.length} warning(s) — see details below)`
          : "";
      setMessageType(errors.length ? "warning" : "success");
      setMessage(
        `Imported ${imported.length} chapter(s), ${itemCount} work item(s), ${fieldCount} field(s).${warn}`,
      );
      if (errors.length) {
        setMessage((prev) => `${prev}\n${errors.slice(0, 5).join("\n")}`);
      }
    } catch (err) {
      setMessageType("error");
      setMessage(err.message || "Failed to read Excel file.");
    } finally {
      setImporting(false);
    }
  };

  return (
    <div className="card" style={{ marginBottom: 14, padding: 14 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
          gap: 12,
          flexWrap: "wrap",
        }}
      >
        <div>
          <div
            style={{
              fontFamily: "var(--font-head)",
              fontWeight: 700,
              fontSize: 14,
              marginBottom: 4,
            }}
          >
            Bulk import from Excel
          </div>
          <div style={{ fontSize: 12, color: "var(--text2)", maxWidth: 520 }}>
            Download the template, fill chapters, work items, and measurement
            fields in one sheet, then upload. The builder will populate
            immediately — no need to add rows one by one in the UI.
          </div>
        </div>
        <div style={{ display: "flex", gap: 8, flexShrink: 0 }}>
          <button
            type="button"
            className="btn btn-outline btn-sm"
            onClick={() => downloadProjectTemplate()}
          >
            Download template
          </button>
          <button
            type="button"
            className="btn btn-primary btn-sm"
            disabled={importing}
            onClick={() => fileRef.current?.click()}
          >
            {importing ? "Importing…" : "Upload Excel"}
          </button>
          <input
            ref={fileRef}
            type="file"
            accept=".xlsx,.xls,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"
            style={{ display: "none" }}
            onChange={handleFile}
          />
        </div>
      </div>
      {message && (
        <div style={{ marginTop: 12 }}>
          <AlertBanner
            type={messageType === "success" ? "success" : messageType === "warning" ? "warning" : "error"}
            message={message}
          />
        </div>
      )}
    </div>
  );
}
