import { getChapterName } from "../../../utils/helpers.js";

export const INDEX_TYPE_OPTIONS = [
  { value: "all", label: "All locations" },
  { value: "span-start", label: "Span start only" },
  { value: "span-end", label: "Span end only" },
  { value: "span", label: "All span endpoints" },
  { value: "photo", label: "Entry photos only" },
];

export const emptyIndexFilters = () => ({
  type: "all",
  search: "",
});

export function hasActiveIndexFilters(f) {
  return f.type !== "all" || !!f.search.trim();
}

export function buildLocationIndexRows(spanMarkers, photoMarkers, indexFilters) {
  const rows = [];

  for (const m of spanMarkers) {
    const [lat, lng] = m.latlng;
    rows.push({
      key: `span-${m.span._id}-${m.type}`,
      kind: m.type === "start" ? "Span start" : "Span end",
      kindKey: m.type === "start" ? "span-start" : "span-end",
      title: m.span.name,
      sub: [m.span.project?.name, m.label].filter(Boolean).join(" · "),
      coords: `${lat.toFixed(5)}, ${lng.toFixed(5)}`,
      status: null,
      photo: null,
      latlng: m.latlng,
    });
  }

  for (const m of photoMarkers) {
    const [lat, lng] = m.latlng;
    rows.push({
      key: `photo-${m.activity._id}-${m.photo._id ?? m.photo.id ?? m.photo.url}`,
      kind: "Photo",
      kindKey: "photo",
      title: m.lineItem.label ?? "Line item",
      sub: [
        m.activity.span?.name,
        getChapterName(m.activity.chapter),
        m.measurement.label,
      ]
        .filter(Boolean)
        .join(" · "),
      coords: `${lat.toFixed(5)}, ${lng.toFixed(5)}`,
      status: m.activity.status,
      photo: m.photo,
      latlng: m.latlng,
    });
  }

  let filtered = rows;

  if (indexFilters.type === "span-start") {
    filtered = filtered.filter((r) => r.kindKey === "span-start");
  } else if (indexFilters.type === "span-end") {
    filtered = filtered.filter((r) => r.kindKey === "span-end");
  } else if (indexFilters.type === "span") {
    filtered = filtered.filter((r) => r.kindKey.startsWith("span"));
  } else if (indexFilters.type === "photo") {
    filtered = filtered.filter((r) => r.kindKey === "photo");
  }

  const q = indexFilters.search.trim().toLowerCase();
  if (q) {
    filtered = filtered.filter(
      (r) =>
        r.title.toLowerCase().includes(q) ||
        r.sub.toLowerCase().includes(q) ||
        r.coords.includes(q) ||
        r.kind.toLowerCase().includes(q),
    );
  }

  return filtered;
}

export function gisFilterSummary(filters, labelCache) {
  const parts = [];
  if (filters.fromDate || filters.toDate) {
    parts.push(`${filters.fromDate || "…"} → ${filters.toDate || "…"}`);
  }
  if (filters.status) parts.push(filters.status);
  if (filters.projects.length) {
    parts.push(
      `${filters.projects.length} project${filters.projects.length !== 1 ? "s" : ""}`,
    );
  }
  if (filters.spans.length) {
    parts.push(`${filters.spans.length} span${filters.spans.length !== 1 ? "s" : ""}`);
  }
  if (filters.createdBy.length) {
    parts.push(
      `${filters.createdBy.length} engineer${filters.createdBy.length !== 1 ? "s" : ""}`,
    );
  }
  return parts.length ? parts.join(" · ") : "All spans and entries with GPS";
}
