import { useMemo } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { Q, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery } from "../../../apollo/useApi.js";
import {
  PageHeader,
  EmptyState,
  Spinner,
} from "../../../components/common/index.jsx";
import {
  buildActivityTableRows,
  parseReportSearchParams,
} from "../../../utils/progressReport.js";

const REPORT_ACTIVITY_LIMIT = 5000;

const PERIOD_COLS = [
  { id: "day", label: "Today" },
  { id: "week", label: "This Week" },
  { id: "month", label: "This Month" },
  { id: "total", label: "Total" },
];

const thStyle = {
  padding: "8px 12px",
  textAlign: "left",
  fontSize: 11,
  fontWeight: 600,
  color: "var(--text2)",
  borderBottom: "1px solid var(--border)",
  whiteSpace: "nowrap",
  background: "rgba(255,255,255,.02)",
};

const tdStyle = {
  padding: "10px 12px",
  fontSize: 12,
  borderBottom: "1px solid var(--border)",
  color: "var(--text)",
  verticalAlign: "middle",
};

function PeriodCell({ data, color }) {
  if (!data || data.achieved === 0) {
    return (
      <td style={{ ...tdStyle, textAlign: "right" }}>
        <span style={{ color: "var(--text3)" }}>—</span>
      </td>
    );
  }
  const textColor =
    data.pct >= 100 ? "var(--green)" : color ?? "var(--accent)";
  return (
    <td style={{ ...tdStyle, textAlign: "right" }}>
      <div style={{ fontWeight: 700, color: textColor, fontSize: 13 }}>
        {data.achieved.toLocaleString("en-IN")}
      </div>
      <div style={{ fontSize: 10, color: "var(--text3)", marginTop: 2 }}>
        {data.pct}% · {data.count}×
      </div>
    </td>
  );
}

function SpanActivityTable({ span, rows, statusLabel }) {
  const summary = PERIOD_COLS.map((p) => {
    const achieved = rows.reduce((s, r) => s + r[p.id].achieved, 0);
    const target = rows.reduce((s, r) => s + r.targetValue, 0);
    const pct =
      target > 0 ? Math.min(100, Math.round((achieved / target) * 100)) : 0;
    return { ...p, pct };
  });

  return (
    <div className="card" style={{ marginBottom: 16 }}>
      <div className="card-header">
        <div>
          <span className="card-title">{span.name}</span>
          <div style={{ fontSize: 11, color: "var(--text2)", marginTop: 4 }}>
            {span.project?.name ?? "—"}
            {statusLabel ? (
              <span style={{ marginLeft: 8 }}>
                · <strong style={{ color: "var(--text)" }}>{statusLabel}</strong> activities
              </span>
            ) : null}
          </div>
        </div>
        <div style={{ display: "flex", gap: 20 }}>
          {summary.map((s) => (
            <div key={s.id} style={{ textAlign: "center" }}>
              <div style={{ fontSize: 10, color: "var(--text3)", marginBottom: 2 }}>
                {s.label}
              </div>
              <div
                style={{
                  fontSize: 15,
                  fontWeight: 700,
                  color:
                    s.pct >= 100
                      ? "var(--green)"
                      : s.pct > 0
                        ? "var(--accent)"
                        : "var(--text3)",
                }}
              >
                {s.pct}%
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th style={thStyle}>Chapter</th>
              <th style={thStyle}>Item</th>
              <th style={thStyle}>Measurement</th>
              <th style={{ ...thStyle, textAlign: "right" }}>Target</th>
              {PERIOD_COLS.map((p) => (
                <th key={p.id} style={{ ...thStyle, textAlign: "right" }}>
                  {p.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.key}>
                <td style={tdStyle}>
                  <span
                    style={{
                      display: "inline-block",
                      width: 8,
                      height: 8,
                      borderRadius: "50%",
                      background: row.chapterColor,
                      marginRight: 6,
                      flexShrink: 0,
                    }}
                  />
                  {row.chapterName}
                </td>
                <td style={tdStyle}>{row.itemLabel}</td>
                <td style={tdStyle}>
                  {row.measurementLabel}
                  {row.unit ? (
                    <span style={{ color: "var(--text3)" }}> ({row.unit})</span>
                  ) : null}
                </td>
                <td style={{ ...tdStyle, textAlign: "right", fontWeight: 600 }}>
                  {row.targetValue.toLocaleString("en-IN")}
                </td>
                {PERIOD_COLS.map((p) => (
                  <PeriodCell key={p.id} data={row[p.id]} color={row.chapterColor} />
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default function ProgressReport() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const filters = useMemo(
    () => parseReportSearchParams(searchParams),
    [searchParams],
  );

  const activityStatus =
    filters.status === "APPROVED" || !filters.status
      ? filters.status || "APPROVED"
      : filters.status;

  const {
    data: activitiesData,
    loading: activitiesLoading,
    error: activitiesError,
    refetch: refetchActivities,
  } = useApiQuery(Q.activities.list, {
    fields: PRESETS.activityReport,
    queryOptions: { pagination: "totalDocuments" },
    variables: {
      limit: REPORT_ACTIVITY_LIMIT,
      status: activityStatus,
      span: filters.spans.length ? filters.spans : undefined,
      project: filters.projects.length ? filters.projects : undefined,
      createdBy: filters.createdBy.length ? filters.createdBy : undefined,
    },
    fetchPolicy: "cache-and-network",
  });

  const {
    data: spansData,
    loading: spansLoading,
    error: spansError,
  } = useApiQuery(Q.spans.list, {
    fields: PRESETS.spanReport,
    variables: {
      page: 1,
      limit: 200,
      projects: filters.projects.length ? filters.projects : undefined,
    },
    fetchPolicy: "cache-and-network",
  });

  const activities = useMemo(
    () => activitiesData?.activities?.data ?? [],
    [activitiesData],
  );
  const allSpans = useMemo(
    () => spansData?.spans?.data ?? [],
    [spansData],
  );

  const reportSpans = useMemo(() => {
    let spans = allSpans.filter((s) => (s.TargetedValues ?? []).length > 0);
    if (filters.spans.length) {
      const ids = new Set(filters.spans.map(String));
      spans = spans.filter((s) => ids.has(String(s._id)));
    }
    return spans;
  }, [allSpans, filters.spans]);

  const spanReports = useMemo(
    () =>
      reportSpans.map((span) => ({
        span,
        rows: buildActivityTableRows(span, activities, {
          statusFilter: activityStatus,
        }),
      })),
    [reportSpans, activities, activityStatus],
  );

  const loading = activitiesLoading || spansLoading;
  const error = activitiesError || spansError;

  const filterPill =
    filters.spans.length > 0 ||
    filters.projects.length > 0 ||
    filters.status ? (
      <div className="card" style={{ marginBottom: 16, padding: "10px 14px" }}>
        <span style={{ fontSize: 11, color: "var(--text2)" }}>
          Filters:{" "}
          {[
            filters.status && `status=${filters.status}`,
            filters.projects.length && `${filters.projects.length} project(s)`,
            filters.spans.length && `${filters.spans.length} span(s)`,
          ]
            .filter(Boolean)
            .join(" · ")}
          {" · "}Counting{" "}
          <strong style={{ color: "var(--text)" }}>{activityStatus}</strong>{" "}
          activities only
        </span>
      </div>
    ) : null;

  return (
    <div className="fade-up">
      <PageHeader
        title="Activity Report"
        subtitle="Span progress tracked against targets — Today · This Week · This Month · Total"
        actions={
          <button
            className="btn btn-outline"
            onClick={() => navigate("/entries")}
          >
            ← Back to Entries
          </button>
        }
      />

      {filterPill}

      {loading && (
        <div style={{ display: "flex", justifyContent: "center", padding: 48 }}>
          <Spinner />
        </div>
      )}

      {!loading && error && (
        <EmptyState
          icon="⚠️"
          title="Failed to load report data"
          message={error.message}
          action={
            <button className="btn btn-outline" onClick={() => refetchActivities()}>
              Retry
            </button>
          }
        />
      )}

      {!loading && !error && reportSpans.length === 0 && (
        <EmptyState
          icon="🎯"
          title="No spans with progress targets"
          message="Configure TargetedValues when creating or editing a span (toggle measurements and set targets per chapter)."
          action={
            <button className="btn btn-outline" onClick={() => navigate("/spans")}>
              Manage Spans
            </button>
          }
        />
      )}

      {!loading &&
        !error &&
        spanReports.map(({ span, rows }) => (
          <SpanActivityTable
            key={span._id}
            span={span}
            rows={rows}
            statusLabel={activityStatus}
          />
        ))}
    </div>
  );
}
