import { useEffect, useRef, useMemo, useState, useCallback } from "react";
import L from "leaflet";
import { Q, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery } from "../../../apollo/useApi.js";
import {
  PageHeader,
  Spinner,
  StatusBadge,
  EmptyState,
  FormField,
} from "../../../components/common/index.jsx";
import CollapsibleSection from "../../field_engineer/new-entry/components/CollapsibleSection.jsx";
import {
  emptyEntryFilters,
  hasActiveEntryFilters,
  activeCountEntry,
  useFacets,
  FilterPanel,
  ActiveChips,
} from "../../../components/common/EntryFilters.jsx";
import { GIS_FILTER_SECTIONS } from "../../../constants/FilterConstants.js";
import {
  collectSpanEndpointMarkers,
  collectPhotoMarkers,
  groupMarkersByLatLng,
  GIS_STATUS_COLORS,
  buildPhotoPopupElement,
  buildSpanGroupPopupElement,
} from "../../../utils/gisMap.js";
import {
  emptyIndexFilters,
  hasActiveIndexFilters,
  buildLocationIndexRows,
  gisFilterSummary,
  INDEX_TYPE_OPTIONS,
} from "./gisFilters.js";
import GisPhotoLightbox from "./GisPhotoLightbox.jsx";
import "../../field_engineer/new-entry/entryForm.css";

const GIS_ACTIVITY_LIMIT = 5000;
const DEFAULT_CENTER = [17.385, 78.49];
const DEFAULT_ZOOM = 11;

function makeEndpointIcon(type, count = 1) {
  const isStart = type === "start";
  const bg = isStart ? "#22C55E" : "#EF4444";
  const letter = isStart ? "S" : "E";
  const badge =
    count > 1
      ? `<span style="position:absolute;top:-6px;right:-8px;min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:#0A1628;color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;border:1.5px solid #fff">${count}</span>`
      : "";
  return L.divIcon({
    className: "",
    iconSize: [28, 28],
    iconAnchor: [14, 14],
    html: `<div style="position:relative;width:28px;height:28px"><div style="width:28px;height:28px;border-radius:4px;background:${bg};border:2.5px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;color:#0A1628;font-family:sans-serif">${letter}</div>${badge}</div>`,
  });
}

function makePhotoIcon(color, count = 1) {
  const badge =
    count > 1
      ? `<span style="position:absolute;top:-6px;right:-8px;min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:#0A1628;color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;border:1.5px solid #fff">${count}</span>`
      : "";
  return L.divIcon({
    className: "",
    iconSize: [20, 20],
    iconAnchor: [10, 10],
    html: `<div style="position:relative;width:18px;height:18px"><div style="width:18px;height:18px;border-radius:50%;background:${color};border:2.5px solid #fff;box-shadow:0 2px 6px rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;font-size:9px">📷</div>${badge}</div>`,
  });
}

function enablePopupInteraction(marker) {
  marker.on("popupopen", (e) => {
    const el = e.popup?.getElement?.();
    if (!el) return;
    L.DomEvent.disableClickPropagation(el);
    L.DomEvent.disableScrollPropagation(el);
  });
}

function activityQueryVariables(filters) {
  return {
    page: 1,
    limit: GIS_ACTIVITY_LIMIT,
    status: filters.status || undefined,
    span: filters.spans.length ? filters.spans : undefined,
    project: filters.projects.length ? filters.projects : undefined,
    createdBy: filters.createdBy.length ? filters.createdBy : undefined,
    fromDate: filters.fromDate
      ? new Date(`${filters.fromDate}T00:00:00`).toISOString()
      : undefined,
    toDate: filters.toDate
      ? new Date(`${filters.toDate}T23:59:59`).toISOString()
      : undefined,
  };
}

export default function GISDashboard() {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markersLayerRef = useRef(null);
  const openPhotoRef = useRef(() => {});
  const [filters, setFilters] = useState(emptyEntryFilters);
  const [indexFilters, setIndexFilters] = useState(emptyIndexFilters);
  const [filtersOpen, setFiltersOpen] = useState(true);
  const [showSpans, setShowSpans] = useState(true);
  const [showPhotos, setShowPhotos] = useState(true);
  const [lightboxPhoto, setLightboxPhoto] = useState(null);

  const { facets, facetLoading, labelCache } = useFacets();

  const openPhoto = useCallback((photo) => {
    setLightboxPhoto(photo);
  }, []);

  openPhotoRef.current = openPhoto;

  const applyFilter = (patch) => setFilters((f) => ({ ...f, ...patch }));
  const resetFilters = () => {
    setFilters(emptyEntryFilters());
    setIndexFilters(emptyIndexFilters());
  };

  const { data: spansData, loading: spansLoading, error: spansError } =
    useApiQuery(Q.spans.list, {
      fields: PRESETS.gisSpans,
      variables: {
        page: 1,
        limit: 500,
        projects: filters.projects.length ? filters.projects : undefined,
        status: undefined,
      },
      fetchPolicy: "cache-and-network",
    });

  const {
    data: activitiesData,
    loading: activitiesLoading,
    error: activitiesError,
  } = useApiQuery(Q.activities.list, {
    fields: PRESETS.gisActivities,
    variables: activityQueryVariables(filters),
    fetchPolicy: "cache-and-network",
  });

  const allSpans = useMemo(
    () => spansData?.spans?.data ?? [],
    [spansData],
  );
  const activities = useMemo(
    () => activitiesData?.activities?.data ?? [],
    [activitiesData],
  );

  const spans = useMemo(() => {
    if (!filters.spans.length) return allSpans;
    const ids = new Set(filters.spans.map(String));
    return allSpans.filter((s) => ids.has(String(s._id)));
  }, [allSpans, filters.spans]);

  const spanMarkers = useMemo(
    () => collectSpanEndpointMarkers(spans),
    [spans],
  );
  const photoMarkers = useMemo(
    () => collectPhotoMarkers(activities),
    [activities],
  );

  const spanGroups = useMemo(
    () => groupMarkersByLatLng(spanMarkers),
    [spanMarkers],
  );
  const photoGroups = useMemo(
    () => groupMarkersByLatLng(photoMarkers),
    [photoMarkers],
  );

  const visibleSpanGroups = useMemo(
    () => (showSpans ? spanGroups : []),
    [showSpans, spanGroups],
  );
  const visiblePhotoGroups = useMemo(
    () => (showPhotos ? photoGroups : []),
    [showPhotos, photoGroups],
  );

  const indexRows = useMemo(
    () => buildLocationIndexRows(spanMarkers, photoMarkers, indexFilters),
    [spanMarkers, photoMarkers, indexFilters],
  );

  const dataFiltersActive = hasActiveEntryFilters(filters);
  const indexFiltersActive = hasActiveIndexFilters(indexFilters);

  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;

    const map = L.map(mapRef.current, {
      center: DEFAULT_CENTER,
      zoom: DEFAULT_ZOOM,
    });
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "© OpenStreetMap contributors",
      maxZoom: 18,
    }).addTo(map);

    markersLayerRef.current = L.layerGroup().addTo(map);
    mapInstanceRef.current = map;

    return () => {
      map.remove();
      mapInstanceRef.current = null;
      markersLayerRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const layer = markersLayerRef.current;
    if (!map || !layer) return;

    layer.clearLayers();
    const bounds = [];

    for (const group of visibleSpanGroups) {
      const types = new Set(group.items.map((m) => m.type));
      const type = types.size === 1 ? group.items[0].type : "start";
      const marker = L.marker(group.latlng, {
        icon: makeEndpointIcon(type, group.items.length),
      });
      marker.bindPopup(buildSpanGroupPopupElement(group.items), {
        maxWidth: 340,
        minWidth: 220,
      });
      enablePopupInteraction(marker);
      marker.addTo(layer);
      bounds.push(group.latlng);
    }

    for (const group of visiblePhotoGroups) {
      const status =
        group.items[0]?.activity?.status ??
        group.items.find((m) => m.activity?.status)?.activity?.status;
      const color = GIS_STATUS_COLORS[status] ?? "#94A3B8";
      const marker = L.marker(group.latlng, {
        icon: makePhotoIcon(color, group.items.length),
      });
      marker.bindPopup(
        buildPhotoPopupElement(group.items, (photo) =>
          openPhotoRef.current(photo),
        ),
        { maxWidth: 340, minWidth: 240, maxHeight: 320 },
      );
      enablePopupInteraction(marker);
      marker.addTo(layer);
      bounds.push(group.latlng);
    }

    if (bounds.length === 1) {
      map.setView(bounds[0], 14);
    } else if (bounds.length > 1) {
      map.fitBounds(bounds, { padding: [48, 48], maxZoom: 14 });
    }
  }, [visibleSpanGroups, visiblePhotoGroups]);

  const loading = spansLoading || activitiesLoading;
  const error = spansError || activitiesError;

  const flyToRow = (row) => {
    const map = mapInstanceRef.current;
    if (!map || !row.latlng) return;
    map.setView(row.latlng, 16, { animate: true });
  };

  return (
    <div className="fade-up emb-entry emb-entry-page">
      <PageHeader
        title="GIS Dashboard"
        subtitle="Filter spans and entries · map and location index stay in sync"
      />

      <div style={{ width: "100%", marginBottom: 16 }}>
        <CollapsibleSection
          step={1}
          title="Map filters"
          summary={gisFilterSummary(filters)}
          isOpen={filtersOpen}
          isComplete={dataFiltersActive}
          isDisabled={false}
          onToggle={() => setFiltersOpen((o) => !o)}
        >
          <FilterPanel
            role="project-admin"
            filters={filters}
            facets={facets}
            facetLoading={facetLoading}
            onChange={applyFilter}
            onReset={resetFilters}
            onClose={() => setFiltersOpen(false)}
            sections={GIS_FILTER_SECTIONS}
            embedded
          />
        </CollapsibleSection>
      </div>

      {dataFiltersActive && (
        <ActiveChips
          sections={GIS_FILTER_SECTIONS}
          filters={filters}
          labelCache={labelCache}
          onChange={applyFilter}
          onReset={resetFilters}
        />
      )}

      <div className="card" style={{ marginBottom: 16 }}>
        <div
          className="card-header"
          style={{ flexWrap: "wrap", gap: 12, alignItems: "flex-start" }}
        >
          <span className="card-title">Map</span>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 16,
              alignItems: "center",
            }}
          >
            <label
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                fontSize: 12,
                color: "var(--text2)",
                cursor: "pointer",
              }}
            >
              <input
                type="checkbox"
                checked={showSpans}
                onChange={(e) => setShowSpans(e.target.checked)}
              />
              <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
                <span
                  style={{
                    width: 14,
                    height: 14,
                    borderRadius: 3,
                    background: "#22C55E",
                    border: "2px solid #fff",
                    fontSize: 8,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontWeight: 800,
                  }}
                >
                  S
                </span>
                <span
                  style={{
                    width: 14,
                    height: 14,
                    borderRadius: 3,
                    background: "#EF4444",
                    border: "2px solid #fff",
                    fontSize: 8,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontWeight: 800,
                  }}
                >
                  E
                </span>
              </span>
              Span endpoints ({spanMarkers.length})
            </label>
            <label
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                fontSize: 12,
                color: "var(--text2)",
                cursor: "pointer",
              }}
            >
              <input
                type="checkbox"
                checked={showPhotos}
                onChange={(e) => setShowPhotos(e.target.checked)}
              />
              <span style={{ fontSize: 12 }}>📷</span>
              Entry photos ({photoMarkers.length})
              {photoGroups.length < photoMarkers.length &&
              photoMarkers.length > 0 ? (
                <span style={{ color: "var(--text3)" }}>
                  · {photoGroups.length} pin
                  {photoGroups.length !== 1 ? "s" : ""}
                </span>
              ) : null}
            </label>
            {Object.entries(GIS_STATUS_COLORS)
              .filter(([s]) =>
                ["APPROVED", "SUBMITTED", "REJECTED"].includes(s),
              )
              .map(([s, c]) => (
                <span
                  key={s}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 5,
                    fontSize: 11,
                    color: "var(--text3)",
                  }}
                >
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: "50%",
                      background: c,
                    }}
                  />
                  {s}
                </span>
              ))}
          </div>
        </div>

        <div style={{ position: "relative" }}>
          {loading && (
            <div
              style={{
                position: "absolute",
                inset: 0,
                zIndex: 500,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: "rgba(0,0,0,.2)",
                borderRadius: "var(--radius-sm)",
              }}
            >
              <Spinner />
            </div>
          )}
          <div className="map-container" ref={mapRef} />
        </div>

        {!loading && !error && (
          <p style={{ fontSize: 11, color: "var(--text3)", marginTop: 10 }}>
            Showing {spanMarkers.length} span endpoint
            {spanMarkers.length !== 1 ? "s" : ""} · {photoMarkers.length} photo
            {photoMarkers.length !== 1 ? "s" : ""}
            {photoGroups.length < photoMarkers.length
              ? ` (${photoGroups.length} stacked locations)`
              : ""}
            {dataFiltersActive
              ? ` · ${activeCountEntry(filters)} data filter${activeCountEntry(filters) !== 1 ? "s" : ""} active`
              : ""}
          </p>
        )}
      </div>

      {error && (
        <EmptyState
          icon="⚠️"
          title="Failed to load map data"
          message={error.message}
        />
      )}

      <GisPhotoLightbox
        photo={lightboxPhoto}
        onClose={() => setLightboxPhoto(null)}
      />

      <div className="card">
        <div
          className="card-header"
          style={{ flexWrap: "wrap", gap: 12, alignItems: "flex-end" }}
        >
          <div>
            <span className="card-title">Location index</span>
            <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 4 }}>
              {indexRows.length} location{indexRows.length !== 1 ? "s" : ""}{" "}
              matching map data
              {indexFiltersActive ? " (index filters applied)" : ""}
            </div>
          </div>
          <div
            className="form-row"
            style={{ margin: 0, minWidth: 280, flex: "1 1 360px", maxWidth: 520 }}
          >
            <FormField label="Location type">
              <select
                className="form-control"
                value={indexFilters.type}
                onChange={(e) =>
                  setIndexFilters((f) => ({ ...f, type: e.target.value }))
                }
              >
                {INDEX_TYPE_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>
                    {o.label}
                  </option>
                ))}
              </select>
            </FormField>
            <FormField label="Search">
              <input
                className="form-control"
                type="search"
                placeholder="Span, item, coordinates…"
                value={indexFilters.search}
                onChange={(e) =>
                  setIndexFilters((f) => ({ ...f, search: e.target.value }))
                }
              />
            </FormField>
          </div>
          {indexFiltersActive && (
            <button
              type="button"
              className="btn btn-outline btn-sm"
              onClick={() => setIndexFilters(emptyIndexFilters())}
            >
              Clear index filters
            </button>
          )}
        </div>

        <div className="table-wrap">
          {indexRows.length === 0 && !loading ? (
            <div
              style={{ padding: 24, textAlign: "center", color: "var(--text3)" }}
            >
              {dataFiltersActive || indexFiltersActive
                ? "No locations match the current filters."
                : "No GPS points yet. Add span start/end coordinates or capture photos with location on field entries."}
            </div>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Name</th>
                  <th>Details</th>
                  <th>GPS (lat, lng)</th>
                  <th>Status</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {indexRows.map((row) => (
                  <tr key={row.key}>
                    <td style={{ fontSize: 12, fontWeight: 600 }}>{row.kind}</td>
                    <td style={{ fontSize: 13 }}>{row.title}</td>
                    <td style={{ fontSize: 11, color: "var(--text2)" }}>
                      {row.sub}
                    </td>
                    <td
                      style={{
                        fontFamily: "monospace",
                        fontSize: 11,
                        color: "var(--text2)",
                      }}
                    >
                      {row.coords}
                    </td>
                    <td>
                      {row.status ? (
                        <StatusBadge status={row.status} />
                      ) : (
                        "—"
                      )}
                    </td>
                    <td style={{ whiteSpace: "nowrap" }}>
                      <button
                        type="button"
                        className="btn btn-ghost btn-sm"
                        onClick={() => flyToRow(row)}
                        title="Show on map"
                      >
                        Map
                      </button>
                      {row.photo ? (
                        <button
                          type="button"
                          className="btn btn-outline btn-sm"
                          onClick={() => openPhoto(row.photo)}
                          style={{ marginLeft: 4 }}
                        >
                          View
                        </button>
                      ) : null}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
